function borrowerDetail(id){const d=db.docs.find(x=>x.id===id);if(!d)return;let dialog=document.getElementById('borrowerDetail');if(!dialog){dialog=document.createElement('dialog');dialog.id='borrowerDetail';document.body.append(dialog)}const f=docFinance(d),client=db.clients.find(c=>c.id===d.client),type=docType(d),definition=documentTypes[type];const value=(label,v)=>`<div class="detail-field"><small>${label}</small><div>${esc(displayDate(v)||'—')}</div></div>`;const address=(label,a,district,city)=>value(label,[a,district,city].filter(Boolean).join(' / '));dialog.innerHTML=`<div class="panelhead"><div><h2>Borçlu Detayı · <span class="debtor-name-emphasis">${esc(d.debtor)}</span></h2><p>${esc(d.number)} · ${esc(type)} · ${esc(client?.name||'')}</p><p><b>Dosya Sorumlusu:</b> ${esc(personnel.find(p=>p.id===d.relatedStaff)?.name||d.relatedStaffName||'Atanmad?')}</p></div><div class="toolbar">${(Array.isArray(d.guarantors)?d.guarantors:[]).map((g,index)=>`<button type="button" class="primary guarantor-top-button" data-top-guarantor="${esc(g.id)}" title="${esc(g.name)}" aria-label="Kefil ${index+1}: ${esc(g.name)}">♙ Kefil ${index+1}</button>`).join('')}<button class="secondary" id="closeBorrower">Kapat</button></div></div><div class="formbody"><div class="settings-tabs borrower-tabs" role="tablist" aria-label="Borçlu föyü bölümleri">${borrowerSheetTabs.map(([key,label])=>`<button type="button" role="tab" id="borrower-tab-${key}" aria-controls="borrower-panel-${key}" data-borrower-tab="${key}">${label}</button>`).join('')}</div><section role="tabpanel" id="borrower-panel-personal" aria-labelledby="borrower-tab-personal" data-borrower-panel="personal"><h3 class="sectiontitle">Borçlu Bilgileri</h3><div class="grid"><div class="detail-field"><small>Ad Soyad / Unvan</small><div class="borrower-sheet-name">${esc(d.debtor||'—')}</div></div>${value('Takip Tarihi',borrowerTrackingDate(d))}${value('TC Kimlik / Vergi No',d.identity)}${value('Tel-1',d.phone1)}${value('Tel-2',d.phone2)}${value('Ref. Tel-1',d.referencePhone1)}${value('Ref. Tel-2',d.referencePhone2)}${value('Ofis Tel-1',d.officePhone1)}${value('Ofis Tel-2',d.officePhone2)}${address('Borçlu Adres-1',d.address,d.district,d.city)}${address('Borçlu Adres-2',d.address2,d.address2District,d.address2City)}${address('Borçlu Adres (Ofis)-3',d.officeAddress3,d.officeAddress3District,d.officeAddress3City)}${(d.additionalPhones||[]).map((phone,i)=>value('Ek Telefon '+(i+1),phone)).join('')}${(d.additionalAddresses||[]).map((a,i)=>address('Ek Adres '+(i+1),a.address,a.district,a.city)).join('')}${value('Dosya Sorumlusu',personnel.find(p=>p.id===d.relatedStaff)?.name||d.relatedStaffName)}</div></section><section role="tabpanel" id="borrower-panel-assets" aria-labelledby="borrower-tab-assets" data-borrower-panel="assets" hidden>${propertySummary(d)}</section><section role="tabpanel" id="borrower-panel-guarantors" aria-labelledby="borrower-tab-guarantors" data-borrower-panel="guarantors" hidden>${guarantorSection(d)}</section><section role="tabpanel" id="borrower-panel-conversations" aria-labelledby="borrower-tab-conversations" data-borrower-panel="conversations" hidden>${borrowerConversationsMarkup(d)}</section><section role="tabpanel" id="borrower-panel-payout" aria-labelledby="borrower-tab-payout" data-borrower-panel="payout" hidden>${clientPayoutSection(d)}</section><section role="tabpanel" id="borrower-panel-finance" aria-labelledby="borrower-tab-finance" data-borrower-panel="finance" hidden><h3 class="sectiontitle" style="margin-top:30px">Finansal Bilgiler</h3><form id="borrowerStatusForm"><div class="grid"><label class="field">Durum<select name="status">${['Derdest','İade','İnfaz','İcra'].map(s=>`<option ${s===(d.status||'Derdest')?'selected':''}>${s}</option>`).join('')}</select></label>${debtorStatus(d)==='İnfaz'?value('İnfaz Tarihi',clientPayoutClosureDate(d)):''}<div class="detail-status-action"><button class="primary">Durumu Kaydet</button></div></div></form><div class="stats" style="margin-top:20px">${[['Anapara',f.principal],['Faiz',isParkingDocument(d)?0:financeCents(d.financeInterest)],['Avukatlık / Hizmet Ücreti',isParkingDocument(d)?0:financeCents(d.financeFee)],['Borçluya Eklenen Masraf',f.expenses],['Yapılandırma İndirimi',f.discount],['Toplam Alacak',f.target],['Tahsil Edilen',f.received],['Kalan Borç',f.remaining]].map(([title,n])=>`<div class="stat"><div><small>${title}</small><strong>${money(n/100)}</strong></div></div>`).join('')}</div><button class="primary" id="borrowerFinancial">Tahsilat</button><button class="secondary" id="borrowerExpense">Masraf</button>${repaymentSection(d)}</section><section role="tabpanel" id="borrower-panel-document" aria-labelledby="borrower-tab-document" data-borrower-panel="document" hidden><h3 class="sectiontitle" style="margin-top:30px">${esc(type)} Bilgileri</h3><div class="grid">${value('Evrak Türü',type)}${isParkingDocument(d)?value('Anlaşılan Ofis Payı (%)',validParkingRate(d)?String(d.parkingCommissionRate):'Belirtilmedi'):''}${value('Evrak Aslı',d.originalDocument||'Belirtilmedi')}${value(definition.serial,d.serial)}${value(definition.due,d.due)}${value('Düzenleme Tarihi',d.issued)}${definition.extras.map(([label,key])=>value(label,d[key])).join('')}${value('Teslim Eden',d.deliveredBy)}${value('Teslim Alan',d.receivedBy)}${value('Kabul Notu',d.notes)}</div>${borrowerAttachmentPreviews(d)}</section></div>`;layoutBorrowerSheet(dialog,d,f,client);setupBorrowerPin(dialog,d);setupBorrowerChain(dialog,d);setupBorrowerDeletion(dialog,d);setupBorrowerNavigation(dialog,id);bindBorrowerSheetTabs(dialog,id);bindGuarantors(d);dialog.querySelectorAll('[data-top-guarantor]').forEach(button=>button.onclick=()=>guarantorDetail(d,button.dataset.topGuarantor));bindBorrowerConversations(d);bindRepayment(d);bindClientPayout(d);$('#closeBorrower').onclick=()=>dialog.close();$('#borrowerFinancial').onclick=()=>{financialOperations(id,$('#borrowerFinancial').dataset.operation||'payment');delete $('#borrowerFinancial').dataset.operation;$('#modal').addEventListener('close',()=>{if(dialog.open)borrowerDetail(id)},{once:true})};$('#borrowerExpense').onclick=()=>{$('#borrowerFinancial').dataset.operation='expense';$('#borrowerFinancial').click()};$('#borrowerStatusForm').onsubmit=e=>{e.preventDefault();const status=e.target.elements.status.value;if(!['Derdest','İade','İnfaz','İcra'].includes(status))return;if(status==='İnfaz'&&docFinance(d).remaining>0)return toast('İnfaz için kalan borç tamamen tahsil edilmelidir.');if(status!=='İnfaz'&&docFinance(d).received>0&&docFinance(d).remaining===0)return toast('Tamamı tahsil edilmiş evrak infaz durumunda kalmalıdır.');if(status==='İcra'&&debtorStatus(d)!=='İcra'){const dialog=document.getElementById('borrowerDetail');if(dialog?.open)dialog.close();return moveBorrowerToEnforcement(id)}const previous=d.status;d.status=status;try{save()}catch{d.status=previous;return toast('Durum kaydedilemedi.')}if(page==='documents')docRows();stats();toast('Evrak durumu kaydedildi.');borrowerDetail(id)};if(!dialog.open){if(document.querySelector('.pinned-borrower-sheet'))dialog.show();else dialog.showModal()}}
