function validateGuarantorExtraAddresses(value,form){for(const [base,prefix] of [['address2','guarantor2'],['officeAddress3','guarantor3']]){for(const name of [base,base+'City',base+'District'])value[name]=String(value[name]||'').trim();if(!value[base]&&!value[base+'City']&&!value[base+'District'])continue;if(!value[base]){form.elements[base].setCustomValidity('Ek adresin açık adresini tamamlayın.');form.elements[base].reportValidity();return false}const city=turkeyCities.find(c=>c.toLocaleLowerCase('tr')===value[base+'City'].toLocaleLowerCase('tr')),district=city&&(turkeyDistricts[city]||[]).find(d=>d.toLocaleLowerCase('tr')===value[base+'District'].toLocaleLowerCase('tr'));if(!city||!district){const input=document.getElementById(prefix+(!city?'City':'District'));input.setCustomValidity('Ek adres için geçerli il ve ilçe seçin.');input.reportValidity();return false}value[base+'City']=city;value[base+'District']=district}return true}
function showBorrowerGuarantors(d){const rows=Array.isArray(d.guarantors)?d.guarantors:[];if(!rows.length)return;if(rows.length===1)return guarantorDetail(d,rows[0].id);const dialog=guarantorDialog();dialog.innerHTML=`<div class="panelhead"><div><h2>Kefil Bilgileri</h2><p>${esc(d.debtor)} · ${rows.length} kefil</p></div><button type="button" class="secondary" id="closeGuarantorList">Kapat</button></div><div class="formbody"><p>Bilgilerini görüntülemek için kefilin adına tıklayın.</p><div class="overflow"><table><thead><tr><th>AD SOYAD</th><th>TELEFON</th></tr></thead><tbody>${rows.map(g=>`<tr><td><button type="button" class="link" data-open-guarantor="${esc(g.id)}">${esc(g.name)}</button></td><td>${esc(g.phone1||g.phone||'—')}</td></tr>`).join('')}</tbody></table></div></div>`;$('#closeGuarantorList').onclick=()=>dialog.close();dialog.querySelectorAll('[data-open-guarantor]').forEach(button=>button.onclick=()=>guarantorDetail(d,button.dataset.openGuarantor));if(!dialog.open)dialog.showModal()}
