function guarantorForm(d,id){const g=(d.guarantors||[]).find(g=>g.id===id)||{},dialog=guarantorDialog();dialog.innerHTML=`<form id="guarantorForm"><div class="panelhead"><div><h2>${id?'Kefili Düzenle':'Kefil Ekle'}</h2><p>Borçlu: ${esc(d.debtor)} · ${esc(d.number)}</p></div><button type="button" class="link" id="closeGuarantorForm">Kapat</button></div><div class="formbody grid">${field('Kefil Ad Soyad','name','text',g.name,true)}${field('TC Kimlik Numarası','identity','text',g.identity,true)}${guarantorPhoneFields(g)}${propertyFields(g,'guarantor')}${clientCityField(g,'guarantor')}<label class="field full">Açık Adres<textarea name="address" rows="3" required>${esc(g.address||'')}</textarea></label>${guarantorExtraAddress(g,'address2','guarantor2','Kefil Adres-2')}${guarantorExtraAddress(g,'officeAddress3','guarantor3','Kefil Adres (Ofis)-3')}<label class="field full">Açıklama / Not<textarea name="notes" rows="3" data-optional="true">${esc(g.notes||'')}</textarea></label></div><div class="actions"><button class="primary">Kefili Kaydet</button></div></form>`;$('#closeGuarantorForm').onclick=()=>dialog.close();if(!dialog.open)dialog.showModal();setupClientCity('guarantor');setupClientDistrict('guarantor');setupClientCity('guarantor2');setupClientDistrict('guarantor2');setupClientCity('guarantor3');setupClientDistrict('guarantor3');configureGuarantorOptionalFields();const form=$('#guarantorForm');bindPropertyFields(form);form.elements.identity.pattern='[0-9]{11}';form.elements.identity.maxLength=11;form.elements.identity.title='11 rakam girin';form.onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(form));if(!validatePropertyFields(v))return;v.name=v.name.trim();v.identity=v.identity.trim();v.phone1=v.phone1.trim();v.phone=v.phone1;v.address=v.address.trim();if(!v.name||!v.phone||!v.address||!/^\d{11}$/.test(v.identity))return toast('Kefilin zorunlu bilgilerini tamamlayın.');if((d.guarantors||[]).some(g=>g.id!==id&&g.identity===v.identity))return toast('Bu TC kimlik numarası bu borçluda zaten kayıtlı.');const city=turkeyCities.find(city=>city.toLocaleLowerCase('tr')===v.city.trim().toLocaleLowerCase('tr')),district=city&&(turkeyDistricts[city]||[]).find(district=>district.toLocaleLowerCase('tr')===v.district.trim().toLocaleLowerCase('tr'));if(!city||!district)return toast('Geçerli il ve ilçe seçin.');if(!validateGuarantorExtraAddresses(v,form))return;const record={...v,id:id||crypto.randomUUID(),city,district,createdAt:g.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()},before=d.guarantors,next=Array.isArray(before)?structuredClone(before):[];if(id){const index=next.findIndex(g=>g.id===id);if(index<0)return toast('Kefil kaydı bulunamadı.');next[index]=record}else next.push(record);d.guarantors=next;if(d._intakeDraft){dialog.close();renderIntakeGuarantors();toast('Kefil evrak taslağına eklendi. Evrakı kaydettiğinizde saklanacak.');return}try{save()}catch{d.guarantors=before;return toast('Kefil kaydedilemedi.')}dialog.close();borrowerDetail(d.id);toast('Kefil bilgileri kaydedildi.')};}
function guarantorDetail(d,id){const g=(d.guarantors||[]).find(g=>g.id===id);if(!g)return;const dialog=guarantorDialog();const item=(label,value)=>`<div class="detail-field"><small>${label}</small><div>${esc(value||'—')}</div></div>`;dialog.innerHTML=`<div class="panelhead"><div><h2>Kefil Bilgileri</h2><p>Borçlu: ${esc(d.debtor)} · ${esc(d.number)}</p></div><button type="button" class="secondary" id="closeGuarantorDetail">Kapat</button></div><div class="formbody grid">${item('Ad Soyad',g.name)}${item('TC Kimlik Numarası',g.identity)}${item('Tel-1',g.phone1||g.phone)}${item('Tel-2',g.phone2)}${item('Ref. Tel-1',g.referencePhone1)}${item('Ref. Tel-2',g.referencePhone2)}${item('Ofis Tel-1',g.officePhone1)}${item('Ofis Tel-2',g.officePhone2)}${item('İl',g.city)}${item('İlçe',g.district)}${item('Açık Adres',g.address)}${item('Kefil Adres-2',[g.address2,g.address2District,g.address2City].filter(Boolean).join(' / '))}${item('Kefil Adres (Ofis)-3',[g.officeAddress3,g.officeAddress3District,g.officeAddress3City].filter(Boolean).join(' / '))}${item('Açıklama / Not',g.notes)}<div class="full">${propertySummary(g)}</div></div><div class="actions"><button type="button" class="primary" id="editGuarantorDetail">Kefili Düzenle</button></div>`;$('#closeGuarantorDetail').onclick=()=>dialog.close();$('#editGuarantorDetail').onclick=()=>guarantorForm(d,g.id);if(!dialog.open)dialog.showModal()}
function editBorrower(id){const d=db.docs.find(d=>d.id===id);if(!d)return;let dialog=document.getElementById('editBorrowerDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='editBorrowerDialog';document.body.append(dialog)}dialog.innerHTML=`<form id="editBorrowerForm"><div class="panelhead"><div><h2>Borçlu Bilgilerini Düzenle</h2><p>${esc(d.number)} · ${esc(docType(d))}</p></div><button type="button" class="secondary" id="cancelEditBorrower">Kapat</button></div><div class="formbody grid">${field('Ad Soyad / Unvan','debtor','text',d.debtor,true)}${field('TC Kimlik / Vergi No','identity','text',d.identity,true)}${field('Tel-1','phone1','tel',d.phone1,true)}${field('Tel-2','phone2','tel',d.phone2)}${field('Ref. Tel-1','referencePhone1','tel',d.referencePhone1)}${field('Ref. Tel-2','referencePhone2','tel',d.referencePhone2)}${field('Ofis Tel-1','officePhone1','tel',d.officePhone1)}${field('Ofis Tel-2','officePhone2','tel',d.officePhone2)}${propertyFields(d,'editDebtor')}${clientCityField(d,'editDebtor')}<label class="field full">Borçlu Açık Adres<textarea name="address" rows="3" required>${esc(d.address||'')}</textarea></label>${guarantorExtraAddress(d,'address2','editDebtor2','Borçlu Adres-2')}${guarantorExtraAddress(d,'officeAddress3','editDebtor3','Borçlu Adres (Ofis)-3')}<label class="field full">Açıklama / Not<textarea name="notes" rows="3" data-optional="true">${esc(d.notes||'')}</textarea></label></div><div class="actions"><button class="primary">Değişiklikleri Kaydet</button></div></form>`;$('#cancelEditBorrower').onclick=()=>dialog.close();if(!dialog.open)dialog.showModal();for(const prefix of ['editDebtor','editDebtor2','editDebtor3']){setupClientCity(prefix);setupClientDistrict(prefix)}const form=$('#editBorrowerForm');bindPropertyFields(form);for(const name of ['phone2','referencePhone1','referencePhone2','officePhone1','officePhone2','address2City','address2District','officeAddress3City','officeAddress3District']){const input=form.elements[name];input.dataset.optional='true';input.required=false;input.setAttribute('aria-required','false');const label=input.id?form.querySelector('label[for="'+input.id+'"]'):input.closest('label');if(label?.firstChild?.nodeType===3)label.firstChild.textContent=label.firstChild.textContent.replace(/\s*\*/g,'')}form.onsubmit=e=>{e.preventDefault();const value=Object.fromEntries(new FormData(form));if(!validatePropertyFields(value))return;for(const key of Object.keys(value))value[key]=value[key].trim();if(!value.debtor||!value.phone1||!value.address||!/^\d{10,11}$/.test(value.identity))return toast('Kimlik, telefon ve adres bilgilerini tamamlayın.');const city=turkeyCities.find(city=>city.toLocaleLowerCase('tr')===value.city.toLocaleLowerCase('tr')),district=city&&(turkeyDistricts[city]||[]).find(district=>district.toLocaleLowerCase('tr')===String(value.district||'').toLocaleLowerCase('tr'));if(!city||!district)return toast('Geçerli il ve ilçe seçin.');for(const [base,prefix] of [['address2','editDebtor2'],['officeAddress3','editDebtor3']]){for(const key of [base,base+'City',base+'District'])value[key]=String(value[key]||'').trim();if(!value[base]&&!value[base+'City']&&!value[base+'District'])continue;const selectedCity=turkeyCities.find(city=>city.toLocaleLowerCase('tr')===value[base+'City'].toLocaleLowerCase('tr')),selectedDistrict=selectedCity&&(turkeyDistricts[selectedCity]||[]).find(district=>district.toLocaleLowerCase('tr')===value[base+'District'].toLocaleLowerCase('tr'));if(!value[base]||!selectedCity||!selectedDistrict)return toast('Ek adresin il, ilçe ve açık adresini tamamlayın.');value[base+'City']=selectedCity;value[base+'District']=selectedDistrict}value.city=city;value.district=district;const before=structuredClone(d);Object.assign(d,value,{updatedAt:new Date().toISOString()});try{save()}catch{Object.keys(d).forEach(k=>delete d[k]);Object.assign(d,before);return toast('Değişiklikler kaydedilemedi.')}dialog.close();if(page==='documents')docRows();stats();const detail=document.getElementById('borrowerDetail');if(detail?.open)borrowerDetail(d.id);toast('Borçlu bilgileri güncellendi.')};}
const propertySections=[['tapu','Tapu'],['vehicle','Araç'],['sgk','SGK']];
function propertyFields(record,prefix){return `<section class="full"><h3 class="sectiontitle">Tapu, Araç ve SGK Bilgileri</h3><div class="grid">${propertySections.map(([key,title])=>{const status=record[key+'Status'];return `<fieldset class="property-field"><legend>${title}</legend><div class="property-options">${['Var','Yok'].map(choice=>`<label><input type="radio" name="${key}Status" value="${choice}" ${status===choice?'checked':''} data-optional="true"> ${choice}</label>`).join('')}</div><div data-property-details="${key}" ${status==='Var'?'':'hidden'}><label class="field" for="${prefix}-${key}-details">${title} Bilgileri<textarea id="${prefix}-${key}-details" name="${key}Details" rows="3" data-optional="true" ${status==='Var'?'required':'disabled'} placeholder="${title} ile ilgili bilgileri yazın…">${esc(record[key+'Details']||'')}</textarea></label></div></fieldset>`}).join('')}${prefix==='intake'?parkingCaptureFields(record):''}</div></section>`}
function bindPropertyFields(form){setupParkingCapture(form);for(const [key] of propertySections){const input=form.elements[key+'Details'],container=form.querySelector('[data-property-details="'+key+'"]');if(!input||!container)continue;function update(){const selected=form.querySelector('input[name="'+key+'Status"]:checked'),show=selected?.value==='Var';container.hidden=!show;input.disabled=!show;input.required=show;input.setAttribute('aria-required',String(show));if(!show)input.setCustomValidity('')}form.querySelectorAll('input[name="'+key+'Status"]').forEach(radio=>radio.addEventListener('change',update));form.addEventListener('reset',()=>queueMicrotask(update));update()}}
function incompletePropertyDescription(root=document){for(const form of root.querySelectorAll('form')){if(form.closest('dialog')&&!form.closest('dialog').open)continue;for(const [key,title] of propertySections){if(form.querySelector('input[name="'+key+'Status"]:checked')?.value==='Var'){const input=form.elements[key+'Details'];if(input&&!input.value.trim())return {input,title}}}}return null}
function blockIncompletePropertyClose(root=document){const missing=incompletePropertyDescription(root);if(!missing)return false;missing.input.setCustomValidity(missing.title+' için Var seçtiniz. Açıklama yazmadan form kapatılamaz.');missing.input.focus();missing.input.reportValidity();toast(missing.title+' açıklamasını doldurun veya Yok seçin.');return true}
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.matches('[data-page]')||/close|cancel/i.test(button.id)){if(blockIncompletePropertyClose()){event.preventDefault();event.stopImmediatePropagation()}}},true);
document.addEventListener('cancel',event=>{if(event.target.tagName==='DIALOG'&&blockIncompletePropertyClose(event.target))event.preventDefault()},true);
window.addEventListener('beforeunload',event=>{if(incompletePropertyDescription()){event.preventDefault();event.returnValue=''}});
function validatePropertyFields(value){for(const [key,title] of propertySections){const status=value[key+'Status'];if(status&&!['Var','Yok'].includes(status)){toast(title+' için Var veya Yok seçin.');return false}value[key+'Details']=status==='Var'?String(value[key+'Details']||'').trim():'';if(status==='Var'&&!value[key+'Details']){toast(title+' bilgilerini doldurun.');return false}}return true}
function propertySummary(record){return `<section style="margin-top:24px"><h3 class="sectiontitle">Tapu, Araç ve SGK Bilgileri</h3><div class="grid">${propertySections.map(([key,title])=>`<div class="detail-field"><small>${title}</small><b>${esc(record[key+'Status']||'Belirtilmedi')}</b>${record[key+'Status']==='Var'?`<p class="conversation-note">${esc(record[key+'Details']||'—')}</p>`:''}</div>`).join('')}${record.docType==='Yediemin Park Ücreti'?'<div class="detail-field"><small>Yakalama</small><b>'+esc(record.captureStatus||'Belirtilmedi')+'</b>'+(record.captureStatus==='Var'?'<p class="conversation-note">'+esc(record.captureDetails||'—')+'</p>':'')+'</div>':''}</div></section>`}
function isParkingDocument(d){return d.docType==='Yediemin Park Ücreti'}
function validParkingRate(d){return d.parkingCommissionRate!==undefined&&d.parkingCommissionRate!==''&&Number.isFinite(Number(d.parkingCommissionRate))&&Number(d.parkingCommissionRate)>=0&&Number(d.parkingCommissionRate)<=100}
function parkingCommission(amount,rate){return Math.round(amount*Number(rate)/100)}
function recognizedEventRevenue(event){return recognizedCollectionRevenue(event,financeEvents,db.docs.find(d=>d.id===event.documentId))}
function borrowerProfit(d){return financeEvents.filter(event=>event.documentId===d.id).reduce((total,event)=>total+(event.type==='payment'?recognizedEventRevenue(event):event.type==='expense'||event.type==='costOnly'?-event.amount:0),0)}
function parkingCommissionMarkup(d,f){if(!isParkingDocument(d))return '';const rate=validParkingRate(d)?Number(d.parkingCommissionRate):null;return `<div class="notice">Yediemin dosyasında yalnızca anapara tahsil edilir. Faiz, vekâlet ücreti ve masraf borçluya eklenmez. Ofis payı anaparanın içinden ayrılır. Kısmi tahsilatta ofis payı kâra yazılmaz; yalnızca tam tahsilatla infaz olduğunda kaydedilir.</div><label class="field">% — Firma ile Anlaşılan Ofis Payı<input type="number" name="parkingCommissionRate" min="0" max="100" step="0.01" required value="${rate??''}"></label>${rate!==null?`<p>Anlaşma: %${new Intl.NumberFormat('tr-TR').format(rate)} · Anapara üzerinden toplam ofis payı: <b>${money(parkingCommission(f.principal,rate)/100)}</b><br>İnfazda gelirleşen ofis payı: <b>${money((f.remaining===0?parkingCommission(f.received,rate):0)/100)}</b> · Firmaya ayrılan: <b>${money((f.received-parkingCommission(f.received,rate))/100)}</b></p>`:'<p>Tahsilattan önce anlaşma yüzdesini girin.</p>'}`}
function conversationNow(){const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Baghdad',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date());const get=key=>parts.find(p=>p.type===key).value;return {date:get('year')+'-'+get('month')+'-'+get('day'),time:get('hour')+':'+get('minute')}}
function conversationNotePreview(note){
  const full=String(note??'');
  const compact=full.replace(/\s+/gu,' ').trim();
  const chars=Array.from(compact);
  if(chars.length<=300)return {full,summary:compact,shortened:false};
  let summary=chars.slice(0,299).join('');
  const boundary=summary.lastIndexOf(' ');
  if(boundary>=200)summary=summary.slice(0,boundary);
  return {full,summary:summary.trimEnd()+'…',shortened:true};
}
function conversationNoteMarkup(note){
  const preview=conversationNotePreview(note);
  return '<p class="conversation-note">'+esc(preview.summary)+'</p>'+(preview.shortened?'<details class="conversation-full-note"><summary>Tam metni göster</summary><p class="conversation-note">'+esc(preview.full)+'</p></details>':'');
}
function borrowerConversationsMarkup(d){const now=conversationNow(),rows=Array.isArray(d.conversations)?d.conversations:[];return `<h3 class="sectiontitle" style="margin-top:30px">Görüşme Süreci</h3><form id="borrowerConversationForm"><div class="grid">${field('Görüşme Tarihi','date','date',now.date,true)}${field('Görüşme Saati','time','time',now.time,true)}<label class="field">Görüşen Personel<input name="staff" value="${esc(hanAuth.name)}" readonly data-optional="true" aria-readonly="true"></label><label class="field">Görüşme Sonucu<select name="result" required><option value="">Sonuç seçin</option>${['Görüşüldü','Ulaşılamadı','Tekrar Aranacak','Ödeme Sözü Alındı','Ödemeyi Reddetti','Raporlandı','İcra Raporu','Diğer'].map(s=>`<option>${s}</option>`).join('')}</select></label><label class="field full">Görüşme / Süreç Notu<textarea name="note" rows="4" data-optional="true" placeholder="Görüşmenin içeriğini ve sonraki adımı yazabilirsiniz…"></textarea></label></div><div class="actions" style="margin-top:15px"><button class="primary">Görüşmeyi Kaydet</button></div></form><div class="conversation-history"><h4>Görüşme Geçmişi (${rows.length})</h4><label class="field conversation-result-filter">Görüşme Sonucuna Göre Süz<select data-conversation-result-filter data-optional="true" aria-label="Görüşme sonucu süzgeci"><option value="">Tüm Sonuçlar</option>${[...new Set(['Görüşüldü','Ulaşılamadı','Tekrar Aranacak','Ödeme Sözü Alındı','Ödemeyi Reddetti','Raporlandı','İcra Raporu','Diğer',...rows.map(r=>r.result)])].filter(Boolean).map(result=>`<option value="${esc(result)}">${esc(result)}</option>`).join('')}</select></label><p data-conversation-filter-count role="status"></p>${rows.slice().sort((a,b)=>(b.date+'T'+b.time).localeCompare(a.date+'T'+a.time)||String(b.createdAt||'').localeCompare(String(a.createdAt||''))).map(row=>`<article class="conversation-entry" data-conversation-result="${esc(row.result)}"><div><strong>${esc(displayDate(row.date))} · ${esc(row.time)}</strong><span class="badge">${esc(row.result)}</span></div><p><b>Görüşen:</b> ${esc(row.staffName||personnel.find(p=>p.id===row.staff)?.name||'—')}</p>${conversationNoteMarkup(row.note)}</article>`).join('')||'<p>Henüz görüşme kaydı yok.</p>'}</div>`}
function bindBorrowerConversations(d){bindLoggedInConversation(d,document.getElementById('borrowerDetail'))}

function businessDate(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Baghdad',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
let dashboardPeriod='day',dashboardDate=businessDate();
function docFinance(d){automaticLegalCharges(d);const events=financeEvents.filter(e=>e.documentId===d.id),received=events.filter(e=>e.type==='payment').reduce((s,e)=>s+e.amount,0),expenses=isParkingDocument(d)?0:events.filter(e=>e.type==='expense').reduce((s,e)=>s+e.amount,0),grossTarget=isParkingDocument(d)?financeCents(d.amount):financeCents(d.amount)+financeCents(d.financeInterest)+financeCents(d.financeFee)+expenses,discount=Number(d.debtDiscountCents||0),target=Math.max(0,grossTarget-discount);return {received,target,grossTarget,discount,expenses,remaining:Math.max(0,target-received),principal:financeCents(d.amount)}}
function periodKeys(period,date){if(period==='day')return [date];if(period==='year')return Array.from({length:12},(_,i)=>date.slice(0,4)+'-'+String(i+1).padStart(2,'0'));const [y,m]=date.split('-').map(Number),days=new Date(Date.UTC(y,m,0)).getUTCDate();return Array.from({length:days},(_,i)=>date.slice(0,7)+'-'+String(i+1).padStart(2,'0'))}
function aggregateFinance(events,period,date,accountingEntries=[]){const costs=accountingEntries.filter(e=>e.type==='out'&&!e.financeEventId).map(e=>({...e,type:'accountingExpense'}));const externalIncome=accountingEntries.filter(e=>e.type==='in'&&e.entryKind==='external'&&e.includeInProfit===true).map(e=>({...e,type:'externalIncome'}));const combined=[...events,...costs,...externalIncome];const keys=periodKeys(period,date);return keys.map(key=>{const rows=combined.filter(e=>period==='year'?e.date.startsWith(key):e.date===key);const payment=rows.filter(e=>e.type==='payment'),collected=payment.reduce((s,e)=>s+e.amount,0),revenue=payment.reduce((s,e)=>s+recognizedCollectionRevenue(e,events,db.docs.find(d=>d.id===e.documentId)),0)+rows.filter(e=>e.type==='externalIncome').reduce((s,e)=>s+e.amount,0),expenses=rows.filter(e=>e.type==='expense'||e.type==='costOnly'||e.type==='accountingExpense').reduce((s,e)=>s+e.amount,0),closed=payment.filter(e=>e.closes);return {key,collected,revenue,expenses,profit:revenue-expenses,closedCount:closed.length,closedAmount:closed.reduce((s,e)=>s+e.closedAmount,0)}})}
function openDashboardDay(date) {
  if (!['ceo', 'admin'].includes(hanAuth.role)) return;
  const financeLabels = {payment: "Tahsilat", expense: "Dosya masrafı", costOnly: "Masraf (borca eklenmedi)"};
  const accountingLabels = {in: "Para girişi", out: "Para çıkışı", transfer: "Hesaplar arası transfer", clientPayout: "Müvekkile anapara ödemesi", advance: "Avans çıkışı"};
  const accounts = new Map(accounting.accounts.map(account => [account.id, account.name]));
  const documents = new Map(db.docs.map(doc => [doc.id, doc]));
  const rows = [
    ...financeEvents.filter(event => event.date === date && Object.hasOwn(financeLabels, event.type)).map(event => {
      const doc = documents.get(event.documentId);
      return {
        ...event,
        label: event.closes && event.type === "payment" ? "Tahsilat · İnfaz" : financeLabels[event.type],
        reference: doc ? [doc.number, doc.debtor].filter(Boolean).join(" · ") : "",
        account: event.accountName || accounts.get(event.accountId)
      };
    }),
    ...accounting.entries.filter(entry => entry.date === date && !entry.financeEventId).map(entry => {
      const account = accounts.get(entry.accountId) || entry.accountName || "—";
      return {
        ...entry,
        label: entry.category || accountingLabels[entry.type] || "Muhasebe işlemi",
        account: entry.type === "transfer" ? account + " → " + (accounts.get(entry.destination) || "—") : account
      };
    })
  ].sort((a, b) => String(a.createdAt || "").localeCompare(String(b.createdAt || "")));
  const cells = rows.map(row => {
    const details = [row.label, row.reference, row.account, row.note, money(row.amount / 100)];
    return "<tr>" + details.map(value => "<td>" + esc(value || "—") + "</td>").join("") + "</tr>";
  }).join("");
  const dialog = $("#modal");
  dialog.innerHTML = `<div class="panelhead"><h2>${esc(displayDate(date))} · Günün İşlemleri</h2><button type="button" class="secondary" data-close-dashboard-day>Kapat</button></div>
    <div class="formbody overflow"><table><thead><tr><th>İŞLEM</th><th>FÖY / BORÇLU</th><th>KASA / BANKA</th><th>AÇIKLAMA</th><th>TUTAR</th></tr></thead>
    <tbody>${cells || '<tr><td colspan="5" class="empty">Bu tarihte kayıtlı işlem yok.</td></tr>'}</tbody></table></div>`;
  dialog.querySelector("[data-close-dashboard-day]").onclick = () => dialog.close();
  dialog.showModal();
}
function dashboard(){if(window.hanAuth&&!['ceo','admin'].includes(hanAuth.role))return staffDashboard();const buckets=aggregateFinance(financeEvents,dashboardPeriod,dashboardDate,accounting.entries),total=buckets.reduce((a,r)=>{for(const k of Object.keys(a))a[k]+=r[k];return a},{collected:0,revenue:0,expenses:0,profit:0,closedCount:0,closedAmount:0});const f=n=>money(n/100);$('#content').innerHTML=`<div class="panel" style="margin-bottom:22px"><div class="panelhead"><div><h2>Gelir ve Tahsilat Özeti</h2><p>İşlem tarihine göre günlük, aylık ve yıllık takip</p></div><div class="toolbar"><label class="field">Görünüm<select id="dashboardPeriod"><option value="day" ${dashboardPeriod==='day'?'selected':''}>Günlük</option><option value="month" ${dashboardPeriod==='month'?'selected':''}>Aylık</option><option value="year" ${dashboardPeriod==='year'?'selected':''}>Yıllık</option></select></label><label class="field">${dashboardPeriod==='day'?'Gün':dashboardPeriod==='month'?'Ay':'Yıl'}<input id="dashboardDate" type="${dashboardPeriod==='day'?'date':dashboardPeriod==='month'?'month':'number'}" value="${dashboardPeriod==='day'?dashboardDate:dashboardPeriod==='month'?dashboardDate.slice(0,7):dashboardDate.slice(0,4)}" ${dashboardPeriod==='year'?'min="1900" max="9999"':''}></label></div></div></div><div class="stats">${[['Tahsilat',f(total.collected)],['Brüt Kâr',f(total.revenue)],['Net Kâr',f(total.profit)],['İnfaz Edilen Evrak',total.closedCount],['İnfaz Edilen Tutar',f(total.closedAmount)],['Toplam Gider',f(total.expenses)]].map(([title,value])=>`<div class="stat"><div><small>${title}</small><strong>${value}</strong></div></div>`).join('')}</div><div class="notice">Kâra eklenmesi seçilen harici para girişleri Brüt Kâr ve Kâr toplamlarına dahildir; diğer harici girişler yalnızca kasa/banka bakiyesini artırır. Tahsilat: seçilen tarihte gelen tüm kısmi ve tam ödemeler; dosyanın derdest, icra, iade veya infaz olmasına bakılmaz. Brüt Kâr: infaz tarihinde, önceki kısmi ödemeler dahil tüm tahsilatın anaparayı aşan kısmı. Net Kâr: geçmiş kısmi ödemeler dahil infaz dosyalarından hesaplanan brüt kâr eksi seçilen dönemin dosya masrafları ve muhasebe giderleri. Muhasebedeki Masraf, Faturalar, Yakıt, SGK, Maaş ve diğer para çıkışları gider toplamına dahildir. Hesaplar arası transferler gider değildir. Yediemin dosyalarında anlaşmalı ofis payı yalnızca tam tahsilatla infaz tarihinde brüt kâra ve kâra yansır; diğer dosyalarda tahsilat önce anaparaya ayrılır. Bu özet, kayıtlı gider tutarlarını kullanır; bordro veya vergi hesaplaması yapmaz. İnfaz, borcun tamamen ödendiği tarihte sayılır.</div><div class="panel"><div class="panelhead"><div><h2>${dashboardPeriod==='year'?'Aylara Göre':dashboardPeriod==='month'?'Günlere Göre':'Günlük'} Dağılım</h2><p>Borçlu masrafları ve Muhasebe bölümündeki giderler işlem tarihine göre birlikte gösterilir.</p></div></div><div class="overflow"><table><thead><tr><th>TARİH</th><th>TAHSİLAT</th><th>BRÜT KÂR</th><th>GİDER</th><th>NET KÂR</th><th>İNFAZ ADEDİ</th><th>İNFAZ TUTARI</th></tr></thead><tbody>${buckets.map(r=>`<tr><td>${dashboardPeriod==='year'?esc(displayDate(r.key)):`<button type="button" class="link" data-dashboard-day="${esc(r.key)}">${esc(displayDate(r.key))}</button>`}</td><td>${f(r.collected)}</td><td>${f(r.revenue)}</td><td>${f(r.expenses)}</td><td>${f(r.profit)}</td><td>${r.closedCount}</td><td>${f(r.closedAmount)}</td></tr>`).join('')}</tbody><tfoot><tr><td><strong>TOPLAM</strong></td>${['collected','revenue','expenses','profit'].map(k=>`<td><strong>${f(total[k])}</strong></td>`).join('')}<td>${total.closedCount}</td><td>${f(total.closedAmount)}</td></tr></tfoot></table></div></div>`;$('#content').querySelectorAll('[data-dashboard-day]').forEach(button=>button.onclick=()=>openDashboardDay(button.dataset.dashboardDay));$('#dashboardPeriod').onchange=e=>{dashboardPeriod=e.target.value;dashboard()};$('#dashboardDate').onchange=e=>{const value=e.target.value;if(!value)return;if(dashboardPeriod==='year'){if(!/^\d{4}$/.test(value)||Number(value)<1900)return;dashboardDate=value+'-01-01'}else dashboardDate=dashboardPeriod==='month'?value+'-01':value;dashboard()};loadPaymentPromisesHome();}
let financeOperationTab='payment';
function financialOperations(id,mode){if(mode)financeOperationTab=mode;const d=db.docs.find(x=>x.id===id);if(!d)return;const f=docFinance(d),locked=financeEvents.some(e=>e.documentId===id&&e.type==='payment');$('#modal').innerHTML=`<div class="panelhead"><div><h2>${esc(d.number)} · Finansal İşlemler</h2><p><span class="debtor-name-emphasis">${esc(d.debtor)}</span> · Kalan: ${money(f.remaining/100)} · Masraf: ${money(f.expenses/100)}</p></div><button class="link" id="closeFinance">Kapat</button></div><form id="financeTerms"><div class="formbody"><h3 class="sectiontitle">Alacak Bileşenleri</h3>${parkingCommissionMarkup(d,f)}<button type="button" class="secondary" id="openLegalCalculator" ${locked?'disabled':""}>Vade Tarihinden Yasal Faiz ve İcra Vekâlet Ücreti Hesapla</button><p>${isParkingDocument(d)?'Yalnız anapara üzerinden tahsilat yapılır.':d.legalCalculationError?esc(d.legalCalculationError):d.legalCalculation?'Yasal faiz ve icra vekâlet ücreti toplam borca dahildir. Hesap tarihi: '+esc(displayDate(d.legalCalculation.end)):''}</p><p>Anapara: ${money(d.amount)} · Masraf: ${money(f.expenses/100)} · Toplam Borç: ${money(f.target/100)}</p><div class="grid">${field('Faiz Tutarı (₺)','interest','number',isParkingDocument(d)?0:d.financeInterest??0,true)}${field('Avukatlık / Hizmet Ücreti (₺)','fee','number',isParkingDocument(d)?0:d.financeFee??0,true)}</div><p>${locked?'Tahsilat olduğu için tutarlar kilitlidir.':'Faiz ve ücret tutarlarını kayıtlı evraka göre girin.'}</p></div><div class="actions"><button class="secondary" ${locked?'disabled':''}>Tutarları Kaydet</button></div></form><form id="financeEntry"><div class="formbody"><h3 class="sectiontitle">Tahsilat Kaydet</h3></div><input type="hidden" name="type" value="payment"><div class="formbody grid">${field('İşlem Tarihi','date','date',businessDate(),true,true)}${field('Tutar (₺)','amount','number','',true)}${collectionAccountField()}${['ceo','admin'].includes(hanAuth.role)?staffSelect('Ciro Personeli (isteğe bağlı)','turnoverStaffId').replace('<select ','<select data-optional="true" ').replace('Personel seçin','Dosya sorumlusu'):''}${field('Açıklama / Dekont No','note','text','',true)}</div><div class="actions"><button type="button" class="secondary" id="latestCollectionReceipt" ${financeEvents.some(e=>e.documentId===id&&e.type==='payment')?'':'disabled'}>Tahsilat Makbuzu</button><button class="primary">İşlemi Kaydet</button></div></form><form id="expenseEntry"><div class="formbody"><h3 class="sectiontitle">Masraf Ekle</h3><p>Toplam kayıtlı masraf: <b>${money(f.expenses/100)}</b></p><div class="notice">Borca Eklemeden Kaydet yalnızca masraf kaydı oluşturur. Masrafı Borca Ekle toplam ve kalan borcu artırır.</div><input type="hidden" name="type" value="expense"><div class="grid">${field('Masraf Tarihi','date','date',businessDate(),true,true)}${field('Masraf Tutarı (₺)','amount','number','',true)}${collectionAccountField('out')}${field('Masraf Açıklaması','note','text','',true,true)}</div></div><div class="actions"><button type="submit" class="secondary" name="saveMode" value="costOnly">Borca Eklemeden Kaydet</button><button type="submit" class="primary" name="saveMode" value="addToDebt">Masrafı Borca Ekle</button></div></form>${financeHistoryMarkup(id)}`;setupFinanceOperationTabs();bindFinanceHistory();$('#latestCollectionReceipt').onclick=()=>{const event=financeEvents.filter(e=>e.documentId===id&&e.type==='payment').at(-1);if(event)openCollectionReceipt(event.id)};$('#openLegalCalculator').disabled=!['ceo','admin'].includes(hanAuth.role)||locked||isParkingDocument(d);$('#openLegalCalculator').onclick=()=>openLegalCalculator(id);if(isParkingDocument(d))$('#expenseEntry').querySelector('[value="addToDebt"]').disabled=true;$('#closeFinance').onclick=()=>$('#modal').close();if(!$('#modal').open)$('#modal').showModal();const terms=$('#financeTerms');for(const el of terms.querySelectorAll('input')){el.min='0';el.step='0.01';if(el.name==='parkingCommissionRate')el.max='100';el.disabled=!['ceo','admin'].includes(hanAuth.role)||locked||(isParkingDocument(d)&&el.name!=='parkingCommissionRate')}terms.onsubmit=e=>{e.preventDefault();if(locked||!['ceo','admin'].includes(hanAuth.role))return;const v=Object.fromEntries(new FormData(terms));if(isParkingDocument(d)){const rate=Number(v.parkingCommissionRate);if(v.parkingCommissionRate===''||!Number.isFinite(rate)||rate<0||rate>100)return toast('Anlaşma yüzdesi 0 ile 100 arasında olmalıdır.');const previous=d.parkingCommissionRate;d.parkingCommissionRate=rate;try{save()}catch{d.parkingCommissionRate=previous;return toast('Oran kaydedilemedi.')}financialOperations(id);return toast('Anlaşma yüzdesi kaydedildi.');}const a=financeCents(v.interest),b=financeCents(v.fee);if(!Number.isSafeInteger(a)||!Number.isSafeInteger(b)||a<0||b<0)return toast('Geçerli tutarlar girin.');const previous=[d.financeInterest,d.financeFee];d.financeInterest=a/100;d.financeFee=b/100;try{save()}catch{[d.financeInterest,d.financeFee]=previous;return toast('Tutarlar saklanamadı.')}financialOperations(id);toast('Alacak tutarları kaydedildi.')};const saveFinanceEntry=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));if(e.target.id==='expenseEntry'&&e.submitter?.value!=='addToDebt')v.type='costOnly';if(!accounting.accounts.some(a=>a.id===v.accountId))return toast(v.type==='payment'?'Paranın girdiği kasa/banka hesabını seçin.':'Paranın çıktığı kasa/banka hesabını seçin.');const operator=activeOperator();if(v.type!=='payment'&&!operator)return toast('Masraf çıkışı için işlem yapan personeli üst bölümden seçin.');const amount=financeCents(v.amount),live=docFinance(d);if(!Number.isSafeInteger(amount)||amount<=0||!v.note.trim())return toast('Tutar ve açıklama girin.');if(!/^\d{4}-\d{2}-\d{2}$/.test(v.date)||v.date>businessDate())return toast('Geçerli bir işlem tarihi girin; gelecek tarihe işlem kaydedilemez.');if(v.type==='expense'&&d.status==='İnfaz')return toast('İnfaz edilmiş evraka yeni masraf eklenemez.');if(isParkingDocument(d)&&v.type==='expense')return toast('Yediemin dosyasında masraf borçluya eklenemez; borca eklemeden kaydedin.');if(isParkingDocument(d)&&v.type==='payment'&&!validParkingRate(d))return toast('Önce anlaşma yüzdesini girip kaydedin.');const prior=financeEvents.filter(e=>e.documentId===id).map(e=>e.date).sort().at(-1);if(prior&&v.date<prior)return toast('Bu evrakta son işlem tarihinden önce giriş yapılamaz.');if(v.type!=='payment'&&amount>accountBalance(v.accountId))return toast('Seçilen kasa/banka hesabında yeterli bakiye yok.');if(v.type==='payment'&&amount>live.remaining)return toast('Tahsilat kalan borcu aşamaz.');const revenuePart=v.type==='payment'?(isParkingDocument(d)?(amount===live.remaining?parkingCommission(live.received+amount,d.parkingCommissionRate):0):Math.max(0,live.received+amount-live.principal)-Math.max(0,live.received-live.principal)):0;const closes=v.type==='payment'&&amount===live.remaining;const event={id:crypto.randomUUID(),documentId:id,type:v.type,date:v.date,amount,accountId:v.accountId,accountName:accounting.accounts.find(a=>a.id===v.accountId).name,operatorId:operator?.id||null,operatorName:operator?.name||'',createdAt:new Date().toISOString(),note:v.note.trim(),revenuePart,principalAtCollection:live.principal,parkingCommissionRate:isParkingDocument(d)?Number(d.parkingCommissionRate):null,clientShare: isParkingDocument(d)&&v.type==='payment'?amount-revenuePart:null,closes,closedAmount:closes?live.target:0};if (v.type === 'payment' && v.turnoverStaffId) {
  const staff = personnel.find(person => person.id === v.turnoverStaffId && person.active);
  if (!staff) return toast('Aktif bir ciro personeli seçin.');
  event.turnoverStaffId = staff.id;
  event.turnoverStaffName = staff.name;
}
financeEvents.push(event);try{localStorage.setItem('hanhukuk-finance-v1',JSON.stringify(financeEvents))}catch{financeEvents.pop();return toast('İşlem saklanamadı.')}if(closes){d.status='İnfaz';d.closedDate=v.date;try{save()}catch{toast('Tahsilat kaydedildi; evrak durumunun saklanması başarısız.')}}financeHistoryTab=v.type==='costOnly'?'costOnly':'all';financialOperations(id);stats();toast(closes?'Tahsilat kaydedildi; evrak infaz edildi.':'İşlem kaydedildi.')};$('#financeEntry').onsubmit=saveFinanceEntry;$('#expenseEntry').onsubmit=saveFinanceEntry}


let financeHistoryTab='all';
function financeHistoryMarkup(id){const entries=financeEvents.filter(e=>e.documentId===id),costs=entries.filter(e=>e.type==='costOnly'),total=costs.reduce((sum,e)=>sum+e.amount,0);return '<div class="formbody"><div class="settings-tabs" role="tablist" aria-label="Finansal kayıtlar"><button type="button" role="tab" id="financeHistoryAllTab" data-history="all" aria-controls="financeHistoryAll">İşlem Geçmişi</button><button type="button" role="tab" id="financeHistoryCostsTab" data-history="costOnly" aria-controls="financeHistoryCosts">Borca Eklenmeyen Masraflar ('+costs.length+')</button></div><section id="financeHistoryAll" role="tabpanel" aria-labelledby="financeHistoryAllTab">'+(entries.slice().reverse().map(e=>'<p>'+esc(displayDate(e.date))+' · '+(e.type==='payment'?'Tahsilat':e.type==='costOnly'?'Masraf (borca eklenmedi)':'Borçlu Masrafı')+' · <b>'+money(e.amount/100)+'</b><br>'+esc(e.note)+(e.accountName?'<br>Hesap: '+esc(e.accountName):'')+(e.operatorName?' · İşlemi yapan: '+esc(e.operatorName):'')+(e.closes?' · İnfaz':'')+(e.type==='payment'?'<br><button type="button" class="secondary" data-collection-receipt="'+esc(e.id)+'">Tahsilat Makbuzu</button>':'')+'</p>').join('')||'<p>Henüz işlem yok.</p>')+'</section><section id="financeHistoryCosts" role="tabpanel" aria-labelledby="financeHistoryCostsTab"><div class="notice">Borca eklenmeyen masraf toplamı: <b>'+money(total/100)+'</b><br>Bu tutarlar borçlunun toplam ve kalan borcuna dahil değildir.</div><div class="overflow"><table><thead><tr><th>TARİH</th><th>AÇIKLAMA</th><th>TUTAR</th></tr></thead><tbody>'+(costs.slice().reverse().map(e=>'<tr><td>'+esc(displayDate(e.date))+'</td><td>'+esc(e.note)+'</td><td>'+money(e.amount/100)+'</td></tr>').join('')||'<tr><td colspan="3" class="empty">Borca eklenmeyen masraf bulunmuyor.</td></tr>')+'</tbody><tfoot><tr><td colspan="2"><b>TOPLAM</b></td><td><b>'+money(total/100)+'</b></td></tr></tfoot></table></div></section></div>'}
function bindFinanceHistory(){document.querySelectorAll('[data-collection-receipt]').forEach(b=>b.onclick=()=>openCollectionReceipt(b.dataset.collectionReceipt));function select(){document.querySelectorAll('[data-history]').forEach(button=>{const active=button.dataset.history===financeHistoryTab;button.classList.toggle('selected',active);button.setAttribute('aria-selected',String(active))});document.getElementById('financeHistoryAll').hidden=financeHistoryTab!=='all';document.getElementById('financeHistoryCosts').hidden=financeHistoryTab!=='costOnly'}document.querySelectorAll('[data-history]').forEach(button=>button.onclick=()=>{financeHistoryTab=button.dataset.history;select()});select()}

function automaticLegalCharges(d){if(typeof applyParkingFee==='function')applyParkingFee(d,businessDate());if(window.hanAuth&&!['ceo','admin'].includes(hanAuth.role))return;if(d.repaymentPlan||isParkingDocument(d))return;if(!d.due||d.status==='İade'||d.status==='İnfaz'||financeEvents.some(e=>e.documentId===d.id&&e.type==='payment'))return;const end=businessDate();const principal=financeCents(d.amount);const key=[end,d.due,principal].join('|');if(d.automaticLegalKey===key)return;try{if(end<'2026-11-03'||end>legalCalculationSupportedThrough)throw Error('Otomatik hesap için güncel tarife ve faiz oranlarının doğrulanması gerekiyor.');const interest=calculateLegalInterest(principal,d.due,end);const base=principal+interest.amount;const fee=calculateEnforcementFee(base,principal,false);const previous={interest:d.financeInterest,fee:d.financeFee,calculation:d.legalCalculation,key:d.automaticLegalKey};d.financeInterest=interest.amount/100;d.financeFee=fee.amount/100;d.legalCalculation={principal,start:d.due,end,interest,base,fee,baseMode:'principalInterest',early:'no',verifiedThrough:legalRateVerifiedThrough,tariff:'AAÜT 03.11.2026 — madde 11',assumption:'Varsayımsal icra takibi; gerçek takip açılmadı',automatic:true,calculatedAt:new Date().toISOString()};d.automaticLegalKey=key;delete d.legalCalculationError;try{save()}catch{d.financeInterest=previous.interest;d.financeFee=previous.fee;d.legalCalculation=previous.calculation;d.automaticLegalKey=previous.key;d.legalCalculationError='Otomatik hesap kaydedilemedi; depolama alanını kontrol edin.'}}catch(error){d.legalCalculationError=error.message}}
const legalRateVerifiedThrough='2026-11-03';
const legalCalculationSupportedThrough='2026-12-31';
const legalRatePeriods=[{start:'2006-01-01',end:'2024-06-01',rate:9},{start:'2024-06-01',end:'2026-07-31',rate:24},{start:'2026-07-31',end:'2027-01-01',rate:31}];
const enforcementTariffBands=[[800000,16],[800000,15],[1600000,14],[1600000,13],[2400000,11],[3200000,8],[4000000,5],[4800000,3],[5600000,2],[Infinity,1]];
function legalDate(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value))throw Error('Geçerli bir tarih girin.');const stamp=Date.parse(value+'T00:00:00Z');if(!Number.isFinite(stamp)||new Date(stamp).toISOString().slice(0,10)!==value)throw Error('Geçersiz tarih.');return stamp}
function calculateLegalInterest(principal,start,end){legalDate(start);legalDate(end);if(!Number.isSafeInteger(principal)||principal<=0)throw Error('Anapara geçersiz.');if(start<'2006-01-01'||end>legalCalculationSupportedThrough)throw Error('Bu tarih aralığı için doğrulanmış faiz oranı bulunmuyor.');if(end<start)throw Error('Hesap tarihi vadeden önce olamaz.');const rows=[];let raw=0;for(const period of legalRatePeriods){const from=start>period.start?start:period.start,to=end<period.end?end:period.end;if(to<=from)continue;const days=(legalDate(to)-legalDate(from))/86400000,interest=principal*period.rate*days/36500;raw+=interest;rows.push({from,to,rate:period.rate,days,interest:Math.round(interest)})}return {amount:Math.round(raw),rows,days:rows.reduce((sum,r)=>sum+r.days,0)}}
function calculateEnforcementFee(base,principal,early=false){if(!Number.isSafeInteger(base)||base<=0||!Number.isSafeInteger(principal)||principal<=0)throw Error('Ücret matrahı geçersiz.');let remaining=base,raw=0;const rows=[];if(base<=78125*100){raw=12500*100;rows.push({amount:base,rate:null,fee:raw})}else for(const [limit,rate] of enforcementTariffBands){if(!remaining)break;const amount=Math.min(remaining,limit*100),fee=amount*rate/100;raw+=fee;remaining-=amount;rows.push({amount,rate,fee:Math.round(fee)})}const capped=Math.min(Math.round(raw),principal),fee=Math.round(capped*(early?.75:1));return {amount:fee,rows,capped,early}}
function openLegalCalculator(id){if(!['ceo','admin'].includes(hanAuth.role))return toast('Faiz ve avukatlık ücretini yalnızca CEO ve yönetici değiştirebilir.');const d=db.docs.find(x=>x.id===id);if(!d)return;if(isParkingDocument(d))return toast('Yediemin dosyasında yalnızca anapara tahsil edilir.');if(financeEvents.some(e=>e.documentId===id&&e.type==='payment'))return toast('Tahsilat bulunan evrakta otomatik yeniden hesaplama yapılamaz.');let dialog=document.getElementById('legalCalculator');if(!dialog){dialog=document.createElement('dialog');dialog.id='legalCalculator';document.body.append(dialog)}dialog.innerHTML=`<form id="legalCalculatorForm"><div class="panelhead"><h2>Yasal Faiz ve İcra Vekâlet Ücreti</h2><button type="button" class="link" id="closeLegal">Kapat</button></div><div class="formbody"><div class="notice">Para alacağı için icra takibi açılmış varsayımıyla ön hesap. Gerçek takip açılmaz. Başlangıç vadedir; başlangıç dahil, hesap tarihi hariç; basit faiz ve 365 gün esası kullanılır. Özel faiz veya ilam hükmü varsa bu hesabı uygulamayın. Oran doğrulama sınırı: ${displayDate(legalRateVerifiedThrough)}. Tarife: 03.11.2026 AAÜT, icra takibi.</div><div class="grid">${field('Vade / Faiz Başlangıcı','start','date',d.due||'',true)}${field('Varsayımsal Takip / Hesap Tarihi','end','date',businessDate(),true)}<label class="field">Vekâlet Ücreti Matrahı<select name="baseMode"><option value="principalInterest">Anapara + hesaplanan işlemiş faiz</option><option value="principal">Yalnız anapara</option></select></label><label class="field">Ödeme Aşaması<select name="early"><option value="no">Tam ücret — ödeme süresi indirimi yok</option><option value="yes">Ödeme süresinde ödeme — dörtte üç ücret</option></select></label></div><p>Anapara: <b>${money(d.amount)}</b> · Masraflar ve vekâlet ücreti faiz matrahına alınmaz.</p><button class="secondary" type="submit">Hesaplamayı Göster</button><div id="legalCalculationOutput" style="margin-top:20px"></div><p><a href="https://mevzuat.adalet.gov.tr/mevzuat/104794" target="_blank" rel="noopener">3095 sayılı Kanun</a> · <a href="https://www.barobirlik.org.tr/dosyalar/belgeler/AvUcretTarifesi/tbb2026.pdf" target="_blank" rel="noopener">AAÜT — madde 11 ve üçüncü kısım</a> · <a href="https://www.tcmb.gov.tr/wps/wcm/connect/TR/TCMB%2BTR/Main%2BMenu/Temel%2BFaaliyetler/Para%2BPolitikasi/Reeskont%2Bve%2BAvans%2BFaiz%2BOranlari?v=1.0.8" target="_blank" rel="noopener">TCMB</a></p></div></form>`;$('#closeLegal').onclick=()=>dialog.close();dialog.showModal();const form=$('#legalCalculatorForm');let result=null;form.oninput=()=>{result=null;$('#legalCalculationOutput').innerHTML=''};form.onchange=form.oninput;form.onsubmit=e=>{e.preventDefault();result=null;try{const v=Object.fromEntries(new FormData(form));if(v.end<'2026-11-03'||v.end>legalCalculationSupportedThrough)throw Error('Seçilen takip tarihi için bu AAÜT sürümü doğrulanmış değil.');const principal=financeCents(d.amount),interest=calculateLegalInterest(principal,v.start,v.end),base=principal+(v.baseMode==='principalInterest'?interest.amount:0),fee=calculateEnforcementFee(base,principal,v.early==='yes');result={...v,principal,interest,base,fee,verifiedThrough:legalRateVerifiedThrough,tariff:'AAÜT 03.11.2026 — madde 11',assumption:'Varsayımsal icra takibi; gerçek takip açılmadı',calculatedAt:new Date().toISOString()};$('#legalCalculationOutput').innerHTML=`<div class="overflow"><table><thead><tr><th>DÖNEM (SON GÜN HARİÇ)</th><th>GÜN</th><th>YILLIK ORAN</th><th>FAİZ</th></tr></thead><tbody>${interest.rows.map(r=>`<tr><td>${displayDate(r.from)} – ${displayDate(r.to)}</td><td>${r.days}</td><td>%${r.rate}</td><td>${money(r.interest/100)}</td></tr>`).join('')}</tbody></table></div><p>Toplam ${interest.days} gün · <b>Faiz: ${money(interest.amount/100)}</b></p><p>Vekâlet matrahı: ${money(base/100)} · Asıl alacak üst sınırı: ${money(principal/100)}<br><b>İcra vekâlet ücreti: ${money(fee.amount/100)}</b>${fee.early?' (dörtte üç ücret)':''}</p><p>Masraflar hariç toplam: <b>${money((principal+interest.amount+fee.amount)/100)}</b></p><label class="settings-check"><input type="checkbox" id="confirmLegal">Vade başlangıcı, genel kanuni faiz, matrah ve seçilen tarifenin bu evraka uygunluğunu kontrol ettim.</label><button type="button" class="primary" id="applyLegal">Hesaplanan Faiz ve Ücreti Borca Uygula</button>`;$('#applyLegal').onclick=()=>{if(!result||!$('#confirmLegal').checked)return toast('Hesabın evraka uygunluğunu kontrol edip işaretleyin.');if(financeEvents.some(e=>e.documentId===id&&e.type==='payment'))return toast('Bu evrakta tahsilat var; tutarlar değiştirilemez.');const previous=structuredClone(d);d.financeInterest=result.interest.amount/100;d.financeFee=result.fee.amount/100;d.legalCalculation=result;try{save()}catch{Object.keys(d).forEach(k=>delete d[k]);Object.assign(d,previous);return toast('Hesap kaydedilemedi.')}dialog.close();financialOperations(id);toast('Hesaplanan faiz ve vekâlet ücreti borca uygulandı.')}}catch(error){$('#legalCalculationOutput').textContent=error.message}}}

function equalInstallments(balance,count){if(!Number.isSafeInteger(balance)||balance<=0||!Number.isInteger(count)||count<1||count>120||count>balance)throw Error('Taksit sayısı 1–120 arasında olmalı; her taksit en az 1 kuruş olmalıdır.');const base=Math.floor(balance/count),remainder=balance%count;return Array.from({length:count},(_,i)=>base+(i<remainder?1:0))}
function installmentMonth(first,index){legalDate(first);const [year,month,day]=first.split('-').map(Number),date=new Date(Date.UTC(year,month-1+index,1)),last=new Date(Date.UTC(date.getUTCFullYear(),date.getUTCMonth()+1,0)).getUTCDate();date.setUTCDate(Math.min(day,last));return date.toISOString().slice(0,10)}
function repaymentSection(d){const plan=d.repaymentPlan,f=docFinance(d);let paidSince=plan?Math.max(0,f.received-plan.receivedAtCreation):0;return `<h3 class="sectiontitle" style="margin-top:30px">Borcu Yapılandır</h3>${d.status==='İnfaz'&&f.remaining===0?'<div class="notice">Bu dosya infaz edilmiştir. Yapılandırma planları ve taksit geçmişi aşağıda görüntülenir; kapanmış borç için yeni plan oluşturulmaz.</div>':''}<div class="notice">Yapılandırılabilir kalan borç: <b>${money(f.remaining/100)}</b>. Plan kaydetmek tahsilat oluşturmaz. Plan kaydedildiğinde mevcut faiz ve ücret tutarları sabitlenir; ek masraflar ayrıca borca yansıyabilir.</div><div class="toolbar"><button type="button" class="primary" id="openRepayment" ${f.remaining===0||d.status==='İade'?'disabled':''}>${plan?((d.repaymentPlanHistory||[]).length+2)+'. Yapılandırma Oluştur':'Borcu Yapılandır'}</button>${paymentPromiseButton(d)}</div>${paymentPromiseSummary(d)}${plan?`<p>${(d.repaymentPlanHistory||[]).length+1}. Yapılandırma · Plan: <b>${esc(plan.method==='equal'?'Eşit Böl':'Manuel Taksitlendirme')}</b> · ${plan.installments.length} taksit · Toplam ${money(plan.balance/100)}${plan.discount?` · İndirim: ${money(plan.discount/100)} · ${esc(plan.discountReason)}`:''}</p>${f.target!==plan.targetAtCreation?'<div class="notice">Plan oluşturulduktan sonra borç toplamı değişti. Yeni kalan borç için planı yeniden düzenleyin.</div>':''}<div class="overflow"><table><thead><tr><th>TAKSİT</th><th>VADE</th><th>TUTAR</th><th>TAHSİL EDİLEN</th><th>KALAN</th></tr></thead><tbody>${plan.installments.map((r,i)=>{const paid=Math.min(r.amount,paidSince);paidSince-=paid;return `<tr><td>${i+1}</td><td>${displayDate(r.due)}</td><td>${money(r.amount/100)}</td><td>${money(paid/100)}</td><td>${money((r.amount-paid)/100)}</td></tr>`}).join('')}</tbody></table></div><p>Tahsilatlar, plan kaydından sonra girilen ödemelerden başlayarak vade sırasıyla taksitlere dağıtılır.</p>`:'<p>Henüz yapılandırma planı yok.</p>'}${repaymentHistoryMarkup(d)}`}
function bindRepayment(d){$('#openRepayment').onclick=()=>openRepayment(d);bindPaymentPromise(d,document.getElementById('borrowerDetail'))}
function openRepayment(d){const finance=docFinance(d);if(!finance.remaining||d.status==='İade')return toast('Bu dosyada yapılandırılabilir borç yok.');let dialog=document.getElementById('repaymentDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='repaymentDialog';document.body.append(dialog)}dialog.innerHTML=`<form id="repaymentForm"><div class="panelhead"><div><h2>Borcu Yapılandır</h2><p>${esc(d.debtor)} · ${esc(d.number)}</p></div><button type="button" class="secondary" id="closeRepayment">Kapat</button></div><div class="formbody"><div class="notice">Kalan borç: <b>${money(finance.remaining/100)}</b>. Kuruş farkları eşit bölmede ilk taksitlere dağıtılır.</div><div class="grid"><label class="field">Yapılandırılacak Borç<select name="settlementMode"><option value="full">Borcun Tamamı</option><option value="discounted">İndirimli Tutar</option></select></label><label class="field">Anlaşılan Yeni Tutar (TL)<input type="text" inputmode="decimal" name="settlementAmount" data-optional="true" disabled value="${formatAmountInput(finance.remaining/100)}"></label><label class="field full">İndirim Açıklaması<input type="text" name="discountReason" data-optional="true" disabled></label><label class="field">Yöntem<select name="method"><option value="equal">Eşit Böl</option><option value="manual">Manuel Taksitlendirme</option></select></label><label class="field">Kaç Taksit?<input type="number" name="count" min="1" max="120" step="1" value="1" required></label>${field('İlk Taksit Tarihi','firstDue','date',businessDate(),true)}</div><button type="button" class="secondary" id="generateInstallments" style="margin-top:18px">Taksitlendir</button><div id="installmentRows" style="margin-top:20px"></div></div></form>`;$('#closeRepayment').onclick=()=>dialog.close();if(!dialog.open)dialog.showModal();const form=$('#repaymentForm');let generated=null;function invalidate(){generated=null;$('#installmentRows').innerHTML=''}function selectedBalance(){if(form.elements.settlementMode.value==='full')return finance.remaining;const parsed=parseAmountInput(form.elements.settlementAmount.value),balance=parsed===null||parsed===''?NaN:financeCents(parsed);if(!Number.isSafeInteger(balance)||balance<=0||balance>=finance.remaining)throw Error('İndirimli tutar sıfırdan büyük ve kalan borçtan küçük olmalıdır.');return balance}form.elements.settlementMode.onchange=()=>{const discounted=form.elements.settlementMode.value==='discounted';for(const name of ['settlementAmount','discountReason']){form.elements[name].disabled=!discounted;form.elements[name].required=discounted}invalidate()};form.elements.settlementAmount.oninput=invalidate;form.elements.settlementAmount.onblur=()=>{const parsed=parseAmountInput(form.elements.settlementAmount.value);if(parsed!==null&&parsed!=='')form.elements.settlementAmount.value=formatAmountInput(parsed)};form.elements.method.onchange=invalidate;form.elements.count.oninput=invalidate;form.elements.firstDue.onchange=invalidate;$('#generateInstallments').onclick=()=>{try{const count=Number(form.elements.count.value),first=form.elements.firstDue.value;legalDate(first);const balance=selectedBalance(),amounts=equalInstallments(balance,count),method=form.elements.method.value;generated={count,first,method,balance};$('#installmentRows').innerHTML=`<div class="overflow"><table><thead><tr><th>TAKSİT</th><th>VADE</th><th>TUTAR (TL)</th></tr></thead><tbody>${amounts.map((amount,i)=>`<tr><td>${i+1}</td><td><label class="field">${i+1}. Taksit Vadesi<input name="due_${i}" type="date" value="${installmentMonth(first,i)}" required></label></td><td><label class="field">${i+1}. Taksit Tutarı<input name="installmentAmount_${i}" type="text" inputmode="decimal" value="${formatAmountInput(amount/100)}" ${method==='equal'?'readonly':''} required></label></td></tr>`).join('')}</tbody></table></div><p id="installmentTotals" role="status" aria-live="polite"></p><button class="primary" type="submit">Yapılandırmayı Kaydet</button>`;form.querySelectorAll('[name^="installmentAmount_"]').forEach(input=>{input.oninput=updateTotals;input.onblur=()=>{const parsed=parseAmountInput(input.value);if(parsed!==null&&parsed!=='')input.value=formatAmountInput(parsed);updateTotals()}});updateTotals()}catch(error){toast(error.message)}};function readRows(){if(!generated)throw Error('Önce Taksitlendir düğmesine basın.');const rows=[];for(let i=0;i<generated.count;i++){const raw=parseAmountInput(form.elements['installmentAmount_'+i].value),amount=raw===null||raw===''?NaN:financeCents(raw),due=form.elements['due_'+i].value;legalDate(due);if(!Number.isSafeInteger(amount)||amount<=0)throw Error('Her taksit için sıfırdan büyük, geçerli tutar girin.');if(i&&due<rows[i-1].due)throw Error('Taksit vadeleri sırayla ilerlemelidir.');rows.push({due,amount})}return rows}function updateTotals(){try{const rows=readRows(),total=rows.reduce((s,r)=>s+r.amount,0),difference=generated.balance-total;$('#installmentTotals').textContent='Taksit Toplamı: '+money(total/100)+' · Yapılandırma Tutarı: '+money(generated.balance/100)+' · Fark: '+money(difference/100)}catch(error){$('#installmentTotals').textContent=error.message}}form.onsubmit=e=>{e.preventDefault();try{if(!generated||generated.count!==Number(form.elements.count.value)||generated.method!==form.elements.method.value||generated.first!==form.elements.firstDue.value||generated.balance!==selectedBalance())throw Error('Değişen bilgilerle yeniden Taksitlendir düğmesine basın.');const rows=readRows(),live=docFinance(d);if(live.remaining!==finance.remaining||live.received!==finance.received||live.target!==finance.target)throw Error('Borç tutarı değişti. Pencereyi kapatıp güncel tutarla yeniden açın.');if(rows.reduce((s,r)=>s+r.amount,0)!==generated.balance)throw Error('Taksit toplamı seçilen yapılandırma tutarına eşit olmalıdır.');const discount=live.remaining-generated.balance,reason=form.elements.discountReason.value.trim();if(discount>0&&!reason)throw Error('İndirim açıklamasını girin.');persistRepaymentPlan(d,{method:generated.method,balance:generated.balance,discount,discountReason:reason,originalBalance:live.remaining,targetAtCreation:live.target-discount,receivedAtCreation:live.received,installments:rows});dialog.close();borrowerDetail(d.id);toast('Yapılandırma planı kaydedildi.')}catch(error){toast(error.message)}}}

let accounting={accounts:[{id:'cash',name:'Nakit Kasa',type:'cash',bank:'',branch:'',holder:'',iban:''}],entries:[]};try{const saved=JSON.parse(localStorage.getItem('hanhukuk-accounting-v1'));if(saved&&Array.isArray(saved.accounts)&&Array.isArray(saved.entries))accounting=saved}catch{}
function activeOperator(){if(window.hanAuth)return {id:hanAuth.id,name:hanAuth.name,active:true};let id='';try{id=sessionStorage.getItem('hanhukuk-active-operator')||''}catch{}return personnel.find(p=>p.id===id&&p.active)||null}
function renderActiveOperator(){const select=document.getElementById('activeOperator');if(!select)return;const current=activeOperator();select.innerHTML='<option value="">Personel seçin</option>'+personnel.filter(p=>p.active).map(p=>`<option value="${esc(p.id)}" ${current?.id===p.id?'selected':''}>${esc(p.name)}</option>`).join('');select.onchange=()=>{try{sessionStorage.setItem('hanhukuk-active-operator',select.value)}catch{toast('Personel seçimi saklanamadı.')}}}
let accountingFilter='',movementFilters={start:'',end:'',type:'',operator:'',category:'',query:''};
function filterAccountMovements(rows,accountId,filters){return rows.filter(e=>(!accountId||e.accountId===accountId)&&(!filters.start||e.date>=filters.start)&&(!filters.end||e.date<=filters.end)&&(!filters.type||(filters.type==='external'?e.type==='in'&&e.entryKind==='external':filters.type==='in'?e.type==='in'&&e.entryKind!=='external':e.type===filters.type))&&(!filters.operator||e.operatorName===filters.operator)&&(!filters.category||e.type==='out'&&e.expenseCategory===filters.category)&&(!filters.query||[e.note,e.label,e.operatorName,e.expenseCategory].some(v=>normalizeSearch(v).includes(normalizeSearch(filters.query)))))}
function saveAccounting(next){try{localStorage.setItem('hanhukuk-accounting-v1',JSON.stringify(next));accounting=next;return true}catch{toast('Muhasebe kaydı saklanamadı.');return false}}
function accountOptions(value=''){return '<option value="">Hesap seçin</option>'+accounting.accounts.map(a=>`<option value="${esc(a.id)}" ${a.id===value?'selected':''}>${esc(a.name)}</option>`).join('')}
function collectionAccountField(direction='in'){return `<label class="field">${direction==='out'?'Paranın Çıktığı Kasa / Banka':'Paranın Girdiği Kasa / Banka'} *<select name="accountId" required>${accountOptions()}</select><small>Hesapları Muhasebe bölümünden ekleyebilirsiniz.</small></label>`}

function accountMovements(){const own=accounting.entries.flatMap(e=>e.type==='transfer'?[{...e,id:e.id+'-out',accountId:e.accountId,signed:-e.amount,label:'Hesaplar arası çıkış'},{...e,id:e.id+'-in',accountId:e.destination,signed:e.amount,label:'Hesaplar arası giriş'}]:[{...e,signed:e.type==='in'?e.amount:-e.amount,label:e.type==='in'?(e.entryKind==='external'?'Haricen para girişi ('+(e.includeInProfit?'kâra eklendi':'kâra eklenmedi')+')':'Para girişi'):e.type==='clientPayout'?'Müvekkile anapara ödemesi':e.type==='advance'?'Avans çıkışı · '+esc(e.advanceType||''):'Para çıkışı'}]);return [...own,...financeEvents.filter(e=>['payment','expense','costOnly'].includes(e.type)&&e.accountId&&!(accounting.excludedFinanceIds||[]).includes(e.id)).map(e=>({...e,signed:e.type==='payment'?e.amount:-e.amount,label:e.type==='payment'?'Borçlu tahsilatı':e.type==='expense'?'Borçlu masrafı':'Masraf (borca eklenmedi)',note:(db.docs.find(d=>d.id===e.documentId)?.number||'Evrak')+' · '+e.note}))].sort((a,b)=>b.date.localeCompare(a.date)||String(b.createdAt||'').localeCompare(String(a.createdAt||'')))}
function accountBalance(id){return accountMovements().filter(e=>e.accountId===id).reduce((sum,e)=>sum+e.signed,0)}
function accountingPage(){if(window.hanAuth&&!['ceo','admin'].includes(hanAuth.role))return staffAccounting();const allRows=accountMovements(),rows=filterAccountMovements(allRows,accountingFilter,movementFilters),operators=[...new Set(allRows.map(e=>e.operatorName).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'tr')),name=id=>accounting.accounts.find(a=>a.id===id)?.name||'Hesap bulunamadı';$('#content').innerHTML=`<div class="panel" style="margin-bottom:22px"><div class="panelhead"><div><h2>Kasa ve Banka Hesapları</h2><p>Para girişlerini, çıkışlarını ve hangi hesapta bulunduğunu izleyin.</p></div><div class="toolbar"><button class="secondary" id="addAccount">＋ Banka / Kasa Ekle</button><button class="primary" id="addCashEntry">Para Hareketi Kaydet</button><button type="button" class="secondary" id="clientPayoutsTab">Müvekkil Ödeme</button></div></div><div class="formbody"><div class="stats">${accounting.accounts.map(a=>`<div class="stat"><div><small>${esc(a.name)} · ${a.type==='bank'?'Banka':'Nakit'}</small><strong>${money(accountBalance(a.id)/100)}</strong><small>${esc(a.iban||a.bank||'Nakit kasa')}</small><button class="link" data-edit-account="${esc(a.id)}">Hesap Bilgileri</button></div></div>`).join('')}</div><p>Toplam hesap bakiyesi: <b>${money(accounting.accounts.reduce((sum,a)=>sum+accountBalance(a.id),0)/100)}</b></p><div class="notice">Borçlu tahsilatlarını Finansal İşlemler ekranından girin; burada tekrar kaydetmeyin. Hesaplar arası transfer ciro veya kâr oluşturmaz. Bu ekran kayıt tutar, bankaya talimat göndermez.</div>${financeEvents.some(e=>e.type==='payment'&&!e.accountId)?'<p>Hesap seçilmeden girilmiş eski tahsilatlar hesap bakiyelerine dahil değildir.</p>':''}</div></div><div class="panel"><div class="panelhead"><h2>Hesap Hareketleri</h2><label class="field">Hesaba Göre Süz<select id="accountingFilter"><option value="">Tüm Hesaplar</option>${accounting.accounts.map(a=>`<option value="${esc(a.id)}" ${accountingFilter===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label></div><form id="movementFilterForm" class="formbody"><div class="grid"><label class="field">Başlangıç Tarihi<input type="date" name="start" data-optional="true" value="${esc(movementFilters.start)}"></label><label class="field">Bitiş Tarihi<input type="date" name="end" data-optional="true" value="${esc(movementFilters.end)}"></label><label class="field">İşlem Türü<select name="type" data-optional="true">${[['','Tüm İşlemler'],['in','Para Girişi'],['external','Haricen Para Girişi'],['out','Para Çıkışı'],['advance','Avans Çıkışı'],['payment','Borçlu Tahsilatı'],['expense','Borçlu Masrafı'],['costOnly','Borca Eklenmeyen Masraf'],['transfer','Hesaplar Arası Transfer'],['clientPayout','Müvekkil Ödemesi']].map(([key,label])=>`<option value="${key}" ${movementFilters.type===key?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">İşlemi Yapan Kullanıcı<select name="operator" data-optional="true"><option value="">Tüm Kullanıcılar</option>${operators.map(n=>`<option value="${esc(n)}" ${movementFilters.operator===n?'selected':''}>${esc(n)}</option>`).join('')}</select></label><label class="field">Gider Kalemi<select name="category" data-optional="true"><option value="">Tüm Gider Kalemleri</option>${accountingExpenseCategories.map(n=>`<option value="${esc(n)}" ${movementFilters.category===n?'selected':''}>${esc(n)}</option>`).join('')}</select></label><label class="field">Açıklama / İşlem Ara<input type="search" name="query" data-optional="true" value="${esc(movementFilters.query)}" placeholder="Açıklama, evrak no veya kullanıcı…"></label></div><div class="toolbar" style="margin-top:16px"><button class="primary" type="submit">Filtrele</button><button class="secondary" type="button" id="clearMovementFilters">Filtreleri Temizle</button></div><p>${rows.length} hareket · Net hareket: <b>${money(rows.reduce((sum,e)=>sum+e.signed,0)/100)}</b>. Tarih aralığı başlangıç ve bitiş günlerini içerir.</p></form><div class="overflow"><table><thead><tr><th>TARİH</th><th>HESAP</th><th>İŞLEM</th><th>GİDER KALEMİ</th><th>İŞLEMİ YAPAN</th><th>AÇIKLAMA</th><th>GİRİŞ</th><th>ÇIKIŞ</th></tr></thead><tbody>${rows.map(e=>`<tr><td>${displayDate(e.date)}</td><td>${esc(name(e.accountId))}</td><td>${e.label}</td><td>${esc(e.type==='out'?(e.expenseCategory||'Belirtilmedi'):'—')}</td><td>${esc(e.operatorName||'Belirtilmedi')}</td><td>${esc(e.note)}</td><td>${e.signed>0?money(e.signed/100):'—'}</td><td>${e.signed<0?money(-e.signed/100):'—'}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">Henüz hesap hareketi yok.</td></tr>'}</tbody><tfoot><tr><td colspan="6"><strong>FİLTRELENEN TOPLAM</strong></td><td><strong>${money(rows.filter(e=>e.signed>0).reduce((sum,e)=>sum+e.signed,0)/100)}</strong></td><td><strong>${money(rows.filter(e=>e.signed<0).reduce((sum,e)=>sum-e.signed,0)/100)}</strong></td></tr></tfoot></table></div></div>`;const filterForm=$('#movementFilterForm');filterForm.onsubmit=e=>{e.preventDefault();if(!filterForm.reportValidity())return;const next=Object.fromEntries(new FormData(filterForm));if(next.start&&next.end&&next.start>next.end)return toast('Başlangıç tarihi bitiş tarihinden sonra olamaz.');movementFilters=next;accountingPage()};$('#clearMovementFilters').onclick=()=>{accountingFilter='';movementFilters={start:'',end:'',type:'',operator:'',category:'',query:''};accountingPage()};$('#addAccount').onclick=()=>accountForm();$('#addCashEntry').onclick=cashEntryForm;$('#clientPayoutsTab').onclick=clientPayoutPage;$('#accountingFilter').onchange=e=>{accountingFilter=e.target.value;accountingPage()};document.querySelectorAll('[data-edit-account]').forEach(b=>b.onclick=()=>accountForm(b.dataset.editAccount))}
function accountForm(id){const a=accounting.accounts.find(a=>a.id===id)||{};$('#modal').innerHTML=`<form id="accountForm"><div class="panelhead"><h2>${id?'Hesap Bilgileri':'Banka / Kasa Ekle'}</h2><button type="button" class="link" id="closeAccount">Kapat</button></div><div class="formbody grid"><label class="field">Hesap Türü<select name="type"><option value="cash" ${a.type==='cash'?'selected':''}>Nakit Kasa</option><option value="bank" ${a.type!=='cash'?'selected':''}>Banka</option></select></label>${field('Hesap Adı','name','text',a.name,true)}<div class="full grid" id="bankFields">${field('Banka Adı','bank','text',a.bank)}${field('Şube','branch','text',a.branch)}${field('Hesap Sahibi','holder','text',a.holder)}${field('IBAN','iban','text',a.iban)}</div></div><div class="actions"><button class="primary">Hesabı Kaydet</button></div></form>`;const form=$('#accountForm');function toggle(){const bank=form.elements.type.value==='bank';$('#bankFields').hidden=!bank;$('#bankFields').querySelectorAll('input').forEach(el=>el.disabled=!bank)}toggle();form.elements.type.onchange=toggle;$('#closeAccount').onclick=()=>$('#modal').close();$('#modal').showModal();form.onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(form));v.name=v.name.trim();if(!v.name)return toast('Hesap adını girin.');if(accounting.accounts.some(a=>a.id!==id&&a.name.toLocaleLowerCase('tr')===v.name.toLocaleLowerCase('tr')))return toast('Bu hesap adı zaten kayıtlı.');if(v.type==='bank'){v.iban=v.iban.replace(/\s/g,'').toUpperCase();if(!validClientIban(v.iban))return toast('Geçerli Türkiye IBAN numarası girin.')}const next=structuredClone(accounting),record={...a,...v,id:id||crypto.randomUUID()};if(id)next.accounts[next.accounts.findIndex(a=>a.id===id)]=record;else next.accounts.push(record);if(saveAccounting(next)){$('#modal').close();accountingPage();toast('Hesap kaydedildi.')}}}
function cashEntryForm(){$('#modal').innerHTML=`<form id="cashEntryForm"><div class="panelhead"><div><h2>Para Hareketi Kaydet</h2><p>İşlemi yapan: ${esc(activeOperator()?.name||'Seçilmedi — önce üst bölümden personel seçin')}</p></div><button type="button" class="link" id="closeCashEntry">Kapat</button></div><div class="formbody grid"><label class="field">İşlem Türü<select name="type"><option value="in">Para Girişi</option><option value="external">Haricen Para Girişi</option><option value="out">Para Çıkışı</option><option value="advance">Avans Çıkışı</option><option value="transfer">Hesaplar Arası Transfer</option></select></label><label class="field" id="advanceTypeField" hidden>Avans Türü *<select name="advanceType" disabled required><option value="">Avans türü seçin</option><option value="T.Ç">T.Ç</option><option value="S.S">S.S</option><option value="Diğer">Diğer</option></select></label><label class="field full" id="externalProfitField" hidden>Kâr Seçimi<select name="profitChoice" disabled required><option value="">Seçin</option><option value="yes">Kâra Ekle</option><option value="no">Kâra Ekleme</option></select></label><label class="field full" id="expenseCategoryField" hidden>Gider Kalemi *<select name="expenseCategory" disabled><option value="">Gider kalemi seçin</option>${accountingExpenseCategories.map(category=>`<option value="${category}">${category}</option>`).join('')}</select></label><label class="field">Hesap<select name="accountId" required>${accountOptions()}</select></label><label class="field full" id="destinationField" hidden>Paranın Gireceği Hesap<select name="destination" disabled>${accountOptions()}</select></label>${field('İşlem Tarihi','date','date',businessDate(),true)}${field('Tutar (TL)','amount','number','',true)}${field('Açıklama / Referans','note','text','',true,true)}</div><div class="actions"><button class="primary">Hareketi Kaydet</button></div></form>`;const form=$('#cashEntryForm');form.elements.type.onchange=()=>{const advance=form.elements.type.value==='advance';$('#advanceTypeField').hidden=!advance;form.elements.advanceType.disabled=!advance;form.elements.advanceType.required=advance;const external=form.elements.type.value==='external';$('#externalProfitField').hidden=!external;const note=form.elements.note;const label=note.closest('label');if(label?.firstChild?.nodeType===3)label.firstChild.textContent=external?'Harici Para Girişi Açıklaması * ':'Açıklama / Referans * ';note.placeholder=external?'Paranın kaynağını ve giriş nedenini yazın…':'';form.elements.profitChoice.disabled=!external;const transfer=form.elements.type.value==='transfer';$('#destinationField').hidden=!transfer;form.elements.destination.disabled=!transfer;form.elements.destination.required=transfer;const out=form.elements.type.value==='out';$('#expenseCategoryField').hidden=!out;form.elements.expenseCategory.disabled=!out;form.elements.expenseCategory.required=out};$('#closeCashEntry').onclick=()=>$('#modal').close();$('#modal').showModal();form.onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(form)),amount=financeCents(v.amount);if(!Number.isSafeInteger(amount)||amount<=0||!v.note.trim())return toast('Geçerli tutar ve açıklama girin.');if(!accounting.accounts.some(a=>a.id===v.accountId))return toast('Hesap seçin.');if(!['in','external','out','advance','transfer'].includes(v.type))return;if(v.type==='external'){if(!['yes','no'].includes(v.profitChoice))return toast('Kâr seçimini yapın.');v.type='in';v.entryKind='external';v.includeInProfit=v.profitChoice==='yes'}delete v.profitChoice;if(v.type==='advance'&&!['T.Ç','S.S','Diğer'].includes(v.advanceType))return toast('Avans türünü seçin.');if(v.type!=='advance')delete v.advanceType;if(v.type==='out'&&!accountingExpenseCategories.includes(v.expenseCategory))return toast('Para çıkışı için gider kalemi seçin.');if(v.type!=='out')delete v.expenseCategory;if(v.type==='transfer'&&(!accounting.accounts.some(a=>a.id===v.destination)||v.destination===v.accountId))return toast('Transfer için farklı bir hedef hesap seçin.');try{legalDate(v.date)}catch{return toast('Geçerli tarih girin.')}if(v.date>businessDate())return toast('Gelecek tarihe gerçekleşmiş işlem girilemez.');if(v.type!=='in'&&amount>accountBalance(v.accountId))return toast('Bu hesapta yeterli bakiye yok.');const operator=activeOperator();if(v.type!=='in'&&!operator)return toast('Para çıkışı için önce üst bölümden işlem yapan personeli seçin.');const next=structuredClone(accounting);next.entries.push({...v,operatorId:operator?.id||null,operatorName:operator?.name||'',id:crypto.randomUUID(),amount,note:v.note.trim(),createdAt:new Date().toISOString()});if(saveAccounting(next)){$('#modal').close();accountingPage();toast('Para hareketi kaydedildi.')}}}

const accountingExpenseCategories=['Masraf','Faturalar','Yakıt','SGK','Maaş','Prim','Kira','Vergi','Ofis Giderleri','Yemek','Ulaşım','Diğer'];

const reportDefinitions={
  excel: {
    label: 'Excel Raporu',
    dateHeader: 'TARİH',
    columns: [
      ['account', 'HESAP'], ['number', 'FÖY NO'], ['trackingDate', 'TKP. TARİHİ'],
      ['principal', 'ASILALACAK', 'money'], ['collection', 'CİRO', 'money'], ['gross', 'BRÜT', 'money'],
      ['debtor', 'BORÇLU'], ['creditor', 'ALACAKLI'], ['staff', 'PERSONEL'], ['status', 'DURUM'], ['department', 'BÖLÜM']
    ]
  },clientDebtorInfo:{label:'Müvekkil Borçlu Bilgi Raporu',hideDate:true,columns:[['status','Föy Durumu'],['debtor','Karşı Yan İsmi'],['due','Alacak Tarihi'],['principal','Asıl Alacak','money'],['enforcement','İcra Durumu'],['identity','T.C.'],['sgk','SSK'],['vehicle','ARAÇ'],['tapu','TAPU'],['received','ÖDEME','money'],['note','AÇIKLAMA']]},clientPayouts:{label:'Müvekkil Ödemeleri',columns:[['number','Evrak No'],['client','Müvekkil'],['debtor','Borçlu'],['account','Kasa / Banka'],['staff','İşlemi Yapan'],['amount','Ödenen Anapara','money'],['note','Açıklama']]},documents:{label:'Evrak ve Borçlu Durumları',columns:[['number','Evrak No'],['client','Müvekkil'],['debtor','Borçlu'],['type','Evrak Türü'],['status','Durum'],['original','Evrak Aslı'],['staff','Dosya Sorumlusu'],['principal','Anapara','money'],['total','Toplam Borç','money'],['received','Tahsilat','money'],['remaining','Kalan','money'],['profit','Kâr','money']]},finance:{label:'Tahsilat, Gider, Ciro ve Kâr',columns:[['number','Evrak No'],['client','Müvekkil'],['debtor','Borçlu'],['kind','İşlem'],['account','Kasa / Banka'],['staff','İşlemi Yapan'],['category','Gider Kalemi'],['collection','Tahsilat','money'],['revenue','Ciro','money'],['expense','Gider','money'],['profit','Kâr','money'],['note','Açıklama']]},accounts:{label:'Kasa / Banka Hareketleri',columns:[['account','Hesap'],['kind','İşlem'],['category','Gider Kalemi'],['staff','İşlemi Yapan'],['incoming','Giriş','money'],['outgoing','Çıkış','money'],['note','Açıklama']]},calls:{label:'Görüşme ve Personel Faaliyetleri',columns:[['number','Evrak No'],['client','Müvekkil'],['debtor','Borçlu'],['time','Saat'],['staff','Görüşen'],['result','Sonuç'],['note','Görüşme Notu']]},installments:{label:'Yapılandırma ve Taksitler',columns:[['number','Evrak No'],['client','Müvekkil'],['debtor','Borçlu'],['sequence','Taksit No'],['method','Plan'],['amount','Taksit Tutarı','money'],['paid','Ödenen','money'],['remaining','Kalan','money'],['status','Taksit Durumu']]},discounts:{label:'Borç İndirimleri',columns:[['number','Evrak No'],['client','Müvekkil'],['debtor','Borçlu'],['before','İndirim Öncesi','money'],['discount','İndirim','money'],['after','İndirim Sonrası','money'],['note','Gerekçe']]},guarantors:{label:'Kefiller',columns:[['number','Evrak No'],['debtor','Borçlu'],['name','Kefil'],['identity','TC Kimlik'],['phone','Tel-1'],['phone2','Tel-2'],['city','İl'],['district','İlçe'],['address','Adres'],['tapu','Tapu'],['vehicle','Araç'],['sgk','SGK']]},clients:{label:'Müvekkil Kayıtları',columns:[['name','Ad / Unvan'],['category','Müvekkil Türü'],['type','Şahıs / Şirket'],['identity','Kimlik / Vergi No'],['phone','Telefon'],['city','İl'],['district','İlçe'],['count','Evrak Adedi'],['principal','Toplam Anapara','money'],['paid','Müvekkile Ödenen','money']]},personnel:{label:'Personel Maaş ve Prim',columns:[['name','Ad Soyad'],['department','Birim'],['status','Durum'],['phone','Telefon'],['official','Resmî Maaş','money'],['unofficial','Gayriresmî Maaş','money'],['salary','Toplam Maaş','money'],['bonus','Prim','money'],['total','Genel Toplam','money']]}};
let reportFilters={type:'finance',from:businessDate().slice(0,7)+'-01',to:businessDate(),client:'',staff:'',status:'',account:'',query:'',undated:true};
function reportLocalDate(value){if(!value)return '';if(/^\d{4}-\d{2}-\d{2}$/.test(value))return value;const date=new Date(value);return Number.isNaN(date.getTime())?'':new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Baghdad',year:'numeric',month:'2-digit',day:'2-digit'}).format(date)}
function reportRows(type){const rows=[],clientName=id=>db.clients.find(c=>c.id===id)?.name||'—',staffName=id=>personnel.find(p=>p.id===id)?.name||'—',accountName=id=>accounting.accounts.find(a=>a.id===id)?.name||'Belirtilmedi';function add(date,doc,cells,meta={}){rows.push({date:reportLocalDate(date),clientId:doc?.client||'',staffId:doc?.relatedStaff||'',status:doc?debtorStatus(doc):'',accountId:'',cells,...meta})}function basic(d){return {number:d.number,client:clientName(d.client),debtor:d.debtor}}
if (type === 'excel') {
  const documents = new Map(db.docs.map(doc => [doc.id, doc]));
  const clients = new Map(db.clients.map(client => [client.id, client]));
  const staff = new Map(personnel.map(person => [person.id, person]));
  for (const payment of financeEvents) {
    if (payment.type !== 'payment') continue;
    const doc = documents.get(payment.documentId);
    const client = clients.get(doc?.client);
    const staffId = payment.turnoverStaffId || payment.collectionStaffId || doc?.relatedStaff || '';
    const person = staff.get(staffId);
    const trackingDate = doc && borrowerTrackingDate(doc);
    add(payment.date, doc, {
      account: payment.accountName || accountName(payment.accountId),
      number: doc?.number,
      trackingDate: trackingDate ? displayDate(trackingDate) : '',
      principal: payment.principalAtCollection ?? (doc ? financeCents(doc.amount) : 0),
      collection: payment.amount,
      gross: recognizedCollectionRevenue(payment, financeEvents, doc),
      debtor: doc?.debtor,
      creditor: client?.tradeName || client?.name,
      staff: payment.turnoverStaffName || payment.collectionStaffName || person?.name || doc?.relatedStaffName,
      status: doc ? debtorStatus(doc) : '',
      department: person?.department
    }, {staffId, accountId: payment.accountId || '', documentId: doc?.id});
  }
}
if(type==='clientPayouts')for(const e of accounting.entries.filter(e=>e.type==='clientPayout')){const d=db.docs.find(d=>d.id===e.documentId);add(e.date,d,{...(d?basic(d):{}),account:e.accountName||accountName(e.accountId),staff:e.operatorName||staffName(e.operatorId),amount:e.amount,note:e.note},{staffId:e.operatorId||'',accountId:e.accountId})}if(type==='documents')for(const d of db.docs){const f=docFinance(d);add(d.created,d,{...basic(d),type:docType(d),status:debtorStatus(d),original:d.originalDocument||'Belirtilmedi',staff:staffName(d.relatedStaff),principal:f.principal,total:f.target,received:f.received,remaining:f.remaining,profit:borrowerProfit(d)})}
if(type==='finance'){for(const e of financeEvents){const d=db.docs.find(d=>d.id===e.documentId),payment=e.type==='payment',expense=['expense','costOnly'].includes(e.type)?e.amount:0,revenue=payment?recognizedEventRevenue(e):0;add(e.date,d,{...(d?basic(d):{}),kind:payment?'Tahsilat':e.type==='costOnly'?'Borca eklenmeyen masraf':'Borçlu masrafı',account:e.accountName||accountName(e.accountId),staff:payment?(e.turnoverStaffName||e.collectionStaffName||staffName(e.turnoverStaffId||e.collectionStaffId||d?.relatedStaff)):e.operatorName||staffName(e.operatorId),category:expense?'Borçlu Masrafı':'—',collection:payment?e.amount:0,revenue,expense,profit:revenue-expense,note:e.note},{staffId:(payment?(e.turnoverStaffId||e.collectionStaffId||d?.relatedStaff):e.operatorId||d?.relatedStaff)||'',accountId:e.accountId||''})}for(const e of accounting.entries.filter(e=>e.type==='out'&&!e.financeEventId))add(e.date,null,{kind:'Muhasebe gideri',account:accountName(e.accountId),staff:e.operatorName||staffName(e.operatorId),category:e.expenseCategory||'Belirtilmedi',collection:0,revenue:0,expense:e.amount,profit:-e.amount,note:e.note},{staffId:e.operatorId||'',accountId:e.accountId})}
if(type==='accounts')for(const e of accountMovements()){const d=db.docs.find(d=>d.id===e.documentId);add(e.date,d,{account:accountName(e.accountId),kind:e.label,category:e.expenseCategory||'—',staff:e.operatorName||staffName(e.operatorId),incoming:Math.max(0,e.signed),outgoing:Math.max(0,-e.signed),note:e.note},{staffId:e.operatorId||'',accountId:e.accountId})}
if(type==='clientDebtorInfo')for(const d of db.docs){const f=docFinance(d);add(d.due||d.created,d,{status:debtorStatus(d),debtor:d.debtor,due:d.due?displayDate(d.due):'—',principal:f.principal,enforcement:debtorStatus(d)==='İcra'?'İcra Açıldı':'- İdari Takip',identity:d.identity||'—',sgk:[d.sgkStatus,d.sgkStatus==='Var'?d.sgkDetails:''].filter(Boolean).join(' · ')||'Belirtilmedi',vehicle:[d.vehicleStatus,d.vehicleStatus==='Var'?d.vehicleDetails:''].filter(Boolean).join(' · ')||'Belirtilmedi',tapu:[d.tapuStatus,d.tapuStatus==='Var'?d.tapuDetails:''].filter(Boolean).join(' · ')||'Belirtilmedi',received:f.received,note:(d.conversations||[]).filter(c=>c.result==='Raporlandı').sort((a,b)=>(a.date+'T'+a.time).localeCompare(b.date+'T'+b.time)).map(c=>[displayDate(c.date),c.time,c.staffName||staffName(c.staff),c.note].filter(Boolean).join(' · ')).join('\n')})}
if(type==='calls')for(const d of db.docs)for(const c of d.conversations||[])add(c.date,d,{...basic(d),time:c.time,staff:c.staffName||staffName(c.staff),result:c.result,note:c.note},{staffId:c.staff});
if(type==='installments')for(const d of db.docs){const p=d.repaymentPlan;if(!p)continue;let paid=Math.max(0,docFinance(d).received-p.receivedAtCreation);p.installments.forEach((r,i)=>{const amount=Math.min(paid,r.amount);paid-=amount;const status=amount===r.amount?'Ödendi':r.due<businessDate()?'Gecikmiş':amount?'Kısmi Ödendi':'Bekliyor';add(r.due,d,{...basic(d),sequence:i+1,method:p.method==='equal'?'Eşit':'Manuel',amount:r.amount,paid:amount,remaining:r.amount-amount,status},{status})})}
if(type==='discounts')for(const d of db.docs)for(const r of d.discountHistory||[])add(r.date,d,{...basic(d),before:r.before,discount:r.amount,after:r.after,note:r.reason});
if(type==='guarantors')for(const d of db.docs)for(const g of d.guarantors||[])add(g.createdAt,d,{...basic(d),name:g.name,identity:g.identity,phone:g.phone1||g.phone,phone2:g.phone2,city:g.city,district:g.district,address:g.address,tapu:g.tapuStatus||'Belirtilmedi',vehicle:g.vehicleStatus||'Belirtilmedi',sgk:g.sgkStatus||'Belirtilmedi'});
if(type==='clients')for(const c of db.clients){const docs=db.docs.filter(d=>d.client===c.id);add(c.createdAt||c.created,null,{name:c.name,category:c.clientCategory,type:c.type,identity:c.identity,phone:c.phone,city:c.city,district:c.district,count:docs.length,principal:docs.reduce((s,d)=>s+financeCents(d.amount),0),paid:docs.reduce((s,d)=>s+clientPayoutTotals(d).paid,0)},{clientId:c.id,staffId:c.collectionStaff||''})}
if(type==='personnel')for(const p of personnel){const f=staffMoney(p);add(p.createdAt,null,{name:p.name,department:p.department,status:p.active?'Aktif':'Pasif',phone:p.phone,official:f.official,unofficial:f.unofficial,salary:f.salary,bonus:f.bonus,total:f.total},{staffId:p.id,status:p.active?'Aktif':'Pasif'})}
return rows.sort((a,b)=>b.date.localeCompare(a.date))}
function filterReportRows(rows,f){return rows.filter(r=>(r.date?(!f.from||r.date>=f.from)&&(!f.to||r.date<=f.to):f.undated)&&(!f.client||r.clientId===f.client)&&(!f.staff||r.staffId===f.staff)&&(!f.status||r.status===f.status)&&(!f.account||r.accountId===f.account)&&normalizeSearch(Object.values(r.cells).join(' ')).includes(normalizeSearch(f.query)))}
function reportCell(row,col){const value=row.cells[col[0]];return col[2]==='money'?money(Number(value||0)/100):String(value??'—')}
function renderReportsPage(){$('#content').innerHTML=`<div class="panel"><div class="panelhead"><div><h2>Rapor Merkezi</h2><p>Kayıtlı işlemleri süzün, yazdırın veya Excel için CSV indirin.</p></div><div class="toolbar"><button class="primary monthly-payroll-report-button" id="openMonthlyPayrollReport">Aylık Maaş ve Prim Raporu</button><button class="primary ins-report-button" id="openInsReport">İNS Raporu</button><button class="primary client-list-report-button" id="openClientListReport">Müvekkil Listesi</button><button class="primary client-debtor-report-button" id="openClientDebtorInfo">Müvekkil Borçlu Bilgi Raporu</button><button class="secondary" id="printReport">Yazdır / PDF</button><button class="primary" id="exportReport">CSV İndir</button></div></div><div class="formbody grid"><label class="field full">Rapor Türü<select id="reportType">${Object.entries(reportDefinitions).map(([id,r])=>`<option value="${id}" ${reportFilters.type===id?'selected':''}>${r.label}</option>`).join('')}</select></label>${field('Başlangıç Tarihi','reportFrom','date',reportFilters.from)}${field('Bitiş Tarihi','reportTo','date',reportFilters.to)}<label class="field">Müvekkil<select id="reportClient"><option value="">Tümü</option>${db.clients.map(c=>`<option value="${c.id}" ${reportFilters.client===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label class="field">Personel<select id="reportStaff"><option value="">Tümü</option>${personnel.map(p=>`<option value="${p.id}" ${reportFilters.staff===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label class="field">Durum<select id="reportStatus"><option value="">Tümü</option>${(reportFilters.type==='personnel'?['Aktif','Pasif']:reportFilters.type==='installments'?['Ödendi','Kısmi Ödendi','Bekliyor','Gecikmiş']:['Derdest','İnfaz','İade','İcra']).map(s=>`<option ${reportFilters.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">Kasa / Banka<select id="reportAccount"><option value="">Tümü</option>${accounting.accounts.map(a=>`<option value="${a.id}" ${reportFilters.account===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><label class="field full">Raporda Ara<input type="search" id="reportQuery" value="${esc(reportFilters.query)}" placeholder="İsim, evrak no, açıklama…"></label><label class="settings-check full"><input type="checkbox" id="reportUndated" ${reportFilters.undated?'checked':''}> Kayıt tarihi bulunmayan eski kayıtları da göster</label><button class="secondary" id="clearReportFilters">Süzgeçleri Temizle</button></div></div><div id="reportResult" style="margin-top:22px"></div>`;function refresh(){const from=document.querySelector('[name="reportFrom"]').value,to=document.querySelector('[name="reportTo"]').value;reportFilters={type:$('#reportType').value,from,to,client:$('#reportClient').value,staff:$('#reportStaff').value,status:$('#reportStatus').value,account:$('#reportAccount').value,query:$('#reportQuery').value,undated:$('#reportUndated').checked};renderReportResult()}$('#reportType').onchange=()=>{reportFilters.type=$('#reportType').value;reportFilters.status='';reportFilters.account='';reportFilters.client='';reportFilters.staff='';reportsPage()};for(const id of ['reportClient','reportStaff','reportStatus','reportAccount','reportUndated'])$('#'+id).onchange=refresh;document.querySelector('[name="reportFrom"]').onchange=refresh;document.querySelector('[name="reportTo"]').onchange=refresh;$('#reportQuery').oninput=refresh;$('#clearReportFilters').onclick=()=>{reportFilters={...reportFilters,from:'',to:'',client:'',staff:'',status:'',account:'',query:'',undated:true};reportsPage()};$('#openClientDebtorInfo').onclick=()=>{reportFilters={...reportFilters,type:'clientDebtorInfo',from:'',to:'',client:'',staff:'',status:'',account:'',query:''};reportsPage()};$('#openMonthlyPayrollReport').onclick=monthlyPayrollReportPage;$('#openInsReport').onclick=insReportPage;$('#openClientListReport').onclick=clientListReportPage;$('#exportReport').onclick=exportReport;$('#printReport').onclick=printReport;renderReportResult()}
function buildCurrentReport(){if(reportFilters.from&&reportFilters.to&&reportFilters.from>reportFilters.to)throw Error('Başlangıç tarihi bitiş tarihinden sonra olamaz.');return {definition:reportDefinitions[reportFilters.type],rows:filterReportRows(reportRows(reportFilters.type),reportFilters)}}
function reportTable(def,rows,openableDocuments){
  const renderCell = (row, column) => {
    const value = esc(reportCell(row, column));
    if (column[0] === 'debtor' && openableDocuments?.has(row.documentId)) {
      return '<button type="button" class="link" data-report-borrower="' + esc(row.documentId) + '">' + value + '</button>';
    }
    return value;
  };if(def.hideDate)return '<div class="overflow"><table><thead><tr>'+def.columns.map(c=>'<th>'+esc(c[1])+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+def.columns.map(c=>'<td style="white-space:pre-line">'+esc(reportCell(r,c))+'</td>').join('')+'</tr>').join('')+'</tbody><tfoot><tr>'+def.columns.map((c,i)=>'<td>'+(i===0?'TOPLAM':c[2]==='money'?money(rows.reduce((sum,r)=>sum+Number(r.cells[c[0]]||0),0)/100):'')+'</td>').join('')+'</tr></tfoot></table></div>';return `<div class="overflow"><table><thead><tr><th>TARİH</th>${def.columns.map(c=>`<th>${esc(c[1])}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td>${r.date?displayDate(r.date):'Tarih yok'}</td>${def.columns.map(c=>`<td>${renderCell(r,c)}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${def.columns.length+1}" class="empty">Bu seçimle eşleşen kayıt yok.</td></tr>`}</tbody><tfoot><tr><td><b>TOPLAM</b></td>${def.columns.map(c=>`<td>${c[2]==='money'?'<b>'+money(rows.reduce((s,r)=>s+Number(r.cells[c[0]]||0),0)/100)+'</b>':''}</td>`).join('')}</tr></tfoot></table></div>`}
function renderReportResult(){try{const {definition,rows}=currentReport();
const result=$('#reportResult');
const openableDocuments=reportFilters.type==='excel'?new Set(db.docs.map(doc=>doc.id)):undefined;
result.innerHTML=`<div class="notice">${rows.length} kayıt · Tarihsiz: ${rows.filter(r=>!r.date).length}. Finansal raporlar işlem tarihini, evrak raporu kayıt tarihini, taksit raporu vade tarihini esas alır. Transferler hesap hareketlerinde giriş ve çıkış olarak görünür; kâr raporunda yer almaz. Personel maaş raporu kayıtlı güncel tutarlardır, dönem bordrosu değildir.</div><div class="panel"><div class="panelhead"><h2>${definition.label}</h2></div>${reportTable(definition,rows,openableDocuments)}</div>`;
result.querySelectorAll("[data-report-borrower]").forEach(button => {
  button.onclick = () => borrowerDetail(button.dataset.reportBorrower);
});
}catch(error){$('#reportResult').textContent=error.message}}
function safeCsvCell(value){let text=String(value??'');if(/^[\s]*[=+\-@\t\r]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"'}
function exportReport(){try{const {definition,rows}=currentReport(),lines=[...(definition.hideDate?[[...definition.columns.map(c=>c[1])],...rows.map(r=>definition.columns.map(c=>reportCell(r,c)))]:[[definition.dateHeader||'Tarih',...definition.columns.map(c=>c[1])],...rows.map(r=>[r.date?displayDate(r.date):'Tarih yok',...definition.columns.map(c=>definition.dateHeader&&c[2]==='money'?(Number(r.cells[c[0]]||0)/100).toFixed(2).replace('.',','):reportCell(r,c))])])] ,blob=new Blob(['\uFEFF'+lines.map(line=>line.map(safeCsvCell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='hanhukuk-'+reportFilters.type+'-'+businessDate()+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(error){toast(error.message)}}
function printReport(){try{const {definition,rows}=currentReport(),frame=document.createElement('iframe');frame.style.cssText='position:fixed;width:0;height:0;border:0';document.body.append(frame);frame.onload=()=>{frame.contentWindow.focus();frame.contentWindow.print();setTimeout(()=>frame.remove(),60000)};frame.srcdoc=`<!doctype html><html lang="tr"><meta charset="utf-8"><title>${esc(definition.label)}</title><style>body{font:10px Arial;color:#182b3a}table{border-collapse:collapse;width:100%}td,th{padding:6px;border:1px solid #ccc;text-align:left;overflow-wrap:anywhere}th{background:#eef2f5}@page{size:A4 landscape;margin:10mm}</style><h1>hanhukuk 1.1.1 · ${esc(definition.label)}</h1><p>${reportFilters.from?displayDate(reportFilters.from):'Başlangıç yok'} – ${reportFilters.to?displayDate(reportFilters.to):'Bitiş yok'} · ${rows.length} kayıt · Oluşturma: ${displayDate(businessDate())}</p>${reportTable(definition,rows)}</html>`}catch(error){toast(error.message)}}

let clientPayoutFilter='',clientPayoutStart='',clientPayoutEnd='';
function clientPayoutClosureDate(d){return d.closedDate||financeEvents.filter(e=>e.documentId===d.id&&e.type==='payment'&&e.closes).map(e=>e.date).sort().at(-1)||''}
function matchesPayoutDate(d,start,end){const date=clientPayoutClosureDate(d);return (!start&&!end)||!!date&&(!start||date>=start)&&(!end||date<=end)}
function clientPayoutTotals(d){const rows=accounting.entries.filter(e=>e.type==='clientPayout'&&e.documentId===d.id),paid=financeCents(d.clientPaidAmount)+rows.reduce((s,e)=>s+e.amount,0),f=docFinance(d),eligible=d.status==='İnfaz'&&f.remaining===0;let entitlement=f.principal;if(isParkingDocument(d))entitlement=validParkingRate(d)?Math.max(0,f.received-parkingCommission(f.received,d.parkingCommissionRate)):0;return {rows,paid,entitlement,remaining:Math.max(0,entitlement-paid),eligible}}
function clientPayoutSection(d){const p=clientPayoutTotals(d);return `<h3 class="sectiontitle" style="margin-top:30px">Müvekkile Ödeme</h3><div class="grid"><div class="detail-field"><small>Müvekkile Ödenecek ${isParkingDocument(d)?'Firma Payı':'Anapara'}</small><b>${money(p.entitlement/100)}</b></div><div class="detail-field"><small>Müvekkile Ödenen</small><b>${money(p.paid/100)}</b></div><div class="detail-field"><small>Müvekkile Kalan Ödeme</small><b>${money(p.remaining/100)}</b></div></div><p>Bu ödeme kasadan/bankadan çıkar; gider veya kâr hesabına dahil edilmez.${isParkingDocument(d)?' Yediemin dosyasında anlaşmalı ofis payı düşülerek firma payı ödenir.':''}</p><button class="primary" type="button" id="payClientFromBorrower" ${!p.eligible||!p.remaining?'disabled':''}>Müvekkile Ödeme Kaydet</button>${!p.eligible?'<p>Ödeme için dosyanın infaz olması ve borçlu bakiyesinin kapanması gerekir.</p>':''}${p.rows.map(e=>`<p>${displayDate(e.date)} · ${money(e.amount/100)} · ${esc(e.accountName||'')} · ${esc(e.operatorName||'')}<br>${esc(e.note)}</p>`).join('')}`}
function bindClientPayout(d){$('#payClientFromBorrower').onclick=()=>clientPayoutForm(d.id)}
function syncPayoutSources(){const ledger=JSON.parse(localStorage.getItem('hanhukuk-accounting-v1')||'null'),events=JSON.parse(localStorage.getItem('hanhukuk-finance-v1')||'null'),records=JSON.parse(localStorage.getItem('icrapro-v1')||'null');if(ledger&&Array.isArray(ledger.accounts)&&Array.isArray(ledger.entries))accounting=ledger;if(Array.isArray(events))financeEvents=events;if(records&&Array.isArray(records.clients)&&Array.isArray(records.docs))db=records}
function clientPayoutPage(){try{syncPayoutSources()}catch{return toast('Ödeme kayıtları okunamadı.')}const list=db.docs.map(d=>({d,p:clientPayoutTotals(d)})).filter(({d,p})=>p.eligible&&p.remaining>0&&matchesPayoutDate(d,clientPayoutStart,clientPayoutEnd)&&(!clientPayoutFilter||d.client===clientPayoutFilter));$('#content').innerHTML=`<div class="panel"><div class="panelhead"><div><h2>Müvekkil Ödemeleri</h2><p>Yalnızca infaz edilmiş ve müvekkile ödemesi tamamlanmamış dosyalar.</p></div><button type="button" class="secondary" id="backAccounting">← Kasa / Banka</button></div><div class="formbody"><form id="clientPayoutDateForm"><div class="grid"><label class="field">İnfaz Tarihi — Başlangıç<input type="date" name="start" data-optional="true" value="${esc(clientPayoutStart)}"></label><label class="field">İnfaz Tarihi — Bitiş<input type="date" name="end" data-optional="true" value="${esc(clientPayoutEnd)}"></label></div><div class="toolbar" style="margin:14px 0"><button type="submit" class="primary">Tarihe Göre Süz</button><button type="button" class="secondary" id="clearPayoutDates">Tarih Filtresini Temizle</button></div><p>Başlangıç ve bitiş günleri dahildir. Tarih filtresi açıkken infaz tarihi bulunmayan dosyalar gösterilmez.</p></form><label class="field">Müvekkile Göre Süz<select id="clientPayoutFilter"><option value="">Tüm Müvekkiller</option>${db.clients.map(c=>`<option value="${c.id}" ${clientPayoutFilter===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><div class="notice" style="margin-top:18px">Müvekkile anapara iadesi gider değildir. Seçilen hesap bakiyesi azalır; ciro ve kâr değişmez. Yediemin dosyasında anlaşmalı ofis payı ayrılır. Bu ekran ödeme kaydı tutar, bankaya havale talimatı göndermez.</div><p>${list.length} dosya · Toplam ödenecek: <b>${money(list.reduce((s,x)=>s+x.p.remaining,0)/100)}</b></p></div><div class="overflow"><table><thead><tr><th>DOSYA</th><th>BORÇLU / MÜVEKKİL</th><th>İNFAZ TARİHİ</th><th>ANAPARA</th><th>ÖDENEN</th><th>ÖDENECEK</th><th>İŞLEM</th></tr></thead><tbody>${list.map(({d,p})=>`<tr><td>${esc(d.number)}<small>${esc(docType(d))}</small></td><td>${esc(d.debtor)}<small>${esc(db.clients.find(c=>c.id===d.client)?.name||'—')}</small></td><td>${esc(displayDate(clientPayoutClosureDate(d))||'—')}</td><td>${money(p.entitlement/100)}</td><td>${money(p.paid/100)}</td><td><b>${money(p.remaining/100)}</b></td><td><button class="primary" type="button" data-client-payout="${d.id}">Ödeme Kaydet</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Müvekkile ödemesi bekleyen infaz dosyası bulunmuyor.</td></tr>'}</tbody><tfoot><tr><td colspan="3"><strong>ALT TOPLAM</strong></td><td><strong>${money(list.reduce((sum,x)=>sum+x.p.entitlement,0)/100)}</strong></td><td><strong>${money(list.reduce((sum,x)=>sum+x.p.paid,0)/100)}</strong></td><td><strong>${money(list.reduce((sum,x)=>sum+x.p.remaining,0)/100)}</strong></td><td></td></tr></tfoot></table></div></div>`;$('#backAccounting').onclick=accountingPage;const dateForm=$('#clientPayoutDateForm');dateForm.onsubmit=e=>{e.preventDefault();if(!dateForm.reportValidity())return;const start=dateForm.elements.start.value,end=dateForm.elements.end.value;if(start&&end&&start>end)return toast('Başlangıç tarihi bitiş tarihinden sonra olamaz.');clientPayoutStart=start;clientPayoutEnd=end;clientPayoutPage()};$('#clearPayoutDates').onclick=()=>{clientPayoutStart='';clientPayoutEnd='';clientPayoutPage()};$('#clientPayoutFilter').onchange=e=>{clientPayoutFilter=e.target.value;clientPayoutPage()};document.querySelectorAll('[data-client-payout]').forEach(b=>b.onclick=()=>clientPayoutForm(b.dataset.clientPayout))}
function clientPayoutForm(id){try{syncPayoutSources()}catch{return toast('Kayıtlar okunamadı.')}const d=db.docs.find(d=>d.id===id);if(!d)return;const p=clientPayoutTotals(d),client=db.clients.find(c=>c.id===d.client);if(!p.eligible||!p.remaining)return toast('Bu dosyada ödenmemiş infaz anaparası yok.');let dialog=document.getElementById('clientPayoutDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='clientPayoutDialog';document.body.append(dialog)}dialog.innerHTML=`<form id="clientPayoutForm"><div class="panelhead"><div><h2>Müvekkile Ödeme Kaydet</h2><p>${esc(d.number)} · ${esc(client?.name||'Müvekkil bulunamadı')}</p></div><button class="secondary" type="button" id="closeClientPayout">Kapat</button></div><div class="formbody"><div class="notice">Ödenecek tutar: <b>${money(p.remaining/100)}</b>. Kayıt gider sayılmaz; seçilen hesaptan düşülür.</div><p>Banka: ${esc(client?.bankName||'—')} · Hesap sahibi: ${esc(client?.accountHolder||'—')}<br>IBAN: ${esc(client?.iban||'—')}</p><div class="grid">${collectionAccountField('out')}${field('Ödeme Tarihi','date','date',businessDate(),true)}${field('Dekont / Ödeme Açıklaması','note','text','',true,true)}</div></div><div class="actions"><button class="primary" type="submit">${money(p.remaining/100)} Ödemeyi Kaydet</button></div></form>`;$('#closeClientPayout').onclick=()=>dialog.close();if(!dialog.open)dialog.showModal();const form=$('#clientPayoutForm');form.onsubmit=e=>{e.preventDefault();try{syncPayoutSources();const current=db.docs.find(d=>d.id===id),live=current&&clientPayoutTotals(current);if(!current||!live.eligible||!live.remaining)throw Error('Bu dosyanın müvekkil ödemesi tamamlanmış veya dosya artık uygun değil.');if(live.remaining!==p.remaining)throw Error('Ödeme tutarı değişti; pencereyi kapatıp yeniden açın.');const v=Object.fromEntries(new FormData(form)),account=accounting.accounts.find(a=>a.id===v.accountId),operator=activeOperator();if(!operator)throw Error('Üst bölümden işlem yapan personeli seçin.');if(!account)throw Error('Paranın çıktığı hesabı seçin.');legalDate(v.date);if(v.date>businessDate())throw Error('Gelecek tarihe gerçekleşmiş ödeme girilemez.');if(current.closedDate&&v.date<current.closedDate)throw Error('Ödeme tarihi infaz tarihinden önce olamaz.');if(!v.note.trim())throw Error('Ödeme açıklamasını girin.');if(accountBalance(account.id)<live.remaining)throw Error('Seçilen hesapta yeterli bakiye yok.');const next=structuredClone(accounting);next.entries.push({id:crypto.randomUUID(),type:'clientPayout',documentId:current.id,clientId:current.client,amount:live.remaining,accountId:account.id,accountName:account.name,operatorId:operator.id,operatorName:operator.name,date:v.date,note:v.note.trim(),createdAt:new Date().toISOString()});if(!saveAccounting(next))return;dialog.close();const borrower=document.getElementById('borrowerDetail');if(borrower?.open)borrowerDetail(id);if(page==='accounting')clientPayoutPage();else if(page==='clients')render();else stats();toast('Müvekkil ödemesi kaydedildi.')}catch(error){toast(error.message)}}}

const borrowerSheetTabs=[['personal','Kimlik ve İletişim'],['assets','Tapu / Araç / SGK'],['guarantors','Kefiller'],['conversations','Görüşmeler'],['document','Evrak Bilgileri'],['payout','Müvekkile Ödeme']];
function bindBorrowerSheetTabs(dialog,id){const active=dialog.dataset.borrowerId===id?dialog.dataset.activeTab:'conversations';dialog.dataset.borrowerId=id;function select(key){if(!borrowerSheetTabs.some(([k])=>k===key))key='personal';dialog.dataset.activeTab=key;dialog.querySelectorAll('[data-borrower-tab]').forEach(b=>{const chosen=b.dataset.borrowerTab===key;b.classList.toggle('selected',chosen);b.setAttribute('aria-selected',String(chosen));b.tabIndex=chosen?0:-1});dialog.querySelectorAll('[data-borrower-panel]').forEach(panel=>panel.hidden=panel.dataset.borrowerPanel!==key)}const buttons=[...dialog.querySelectorAll('[data-borrower-tab]')];buttons.forEach((b,index)=>{b.onclick=()=>select(b.dataset.borrowerTab);b.onkeydown=event=>{let next;if(event.key==='ArrowRight')next=(index+1)%buttons.length;else if(event.key==='ArrowLeft')next=(index+buttons.length-1)%buttons.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=buttons.length-1;else return;event.preventDefault();select(buttons[next].dataset.borrowerTab);buttons[next].focus()}});select(active)}

function persistRepaymentPlan(d,plan){const before=structuredClone(d);if(plan.discount>0){d.debtDiscountCents=Number(d.debtDiscountCents||0)+plan.discount;d.discountHistory=[...(d.discountHistory||[]),{amount:plan.discount,reason:plan.discountReason,date:new Date().toISOString(),before:plan.originalBalance,after:plan.balance}]}if(d.repaymentPlan)d.repaymentPlanHistory=[...(d.repaymentPlanHistory||[]),structuredClone(d.repaymentPlan)];d.repaymentPlan={...plan,id:crypto.randomUUID(),createdAt:new Date().toISOString()};try{save()}catch{Object.keys(d).forEach(k=>delete d[k]);Object.assign(d,before);throw Error('Yapılandırma kaydedilemedi.')}}
function repaymentHistoryMarkup(d){const history=d.repaymentPlanHistory||[];return history.length?'<details '+(d.status==='İnfaz'?'open ':'')+'style="margin-top:20px"><summary>Önceki Yapılandırmalar ('+history.length+')</summary>'+history.map((p,i)=>'<div class="notice" style="margin-top:12px"><b>'+(i+1)+'. Yapılandırma</b> · '+displayDate(p.createdAt)+' · '+money(p.balance/100)+'<div class="overflow"><table><thead><tr><th>TAKSİT</th><th>VADE</th><th>TUTAR</th></tr></thead><tbody>'+p.installments.map((r,j)=>'<tr><td>'+(j+1)+'</td><td>'+displayDate(r.due)+'</td><td>'+money(r.amount/100)+'</td></tr>').join('')+'</tbody></table></div></div>').join('')+'</details>':''}

function parkingCaptureFields(record){return `<fieldset class="property-field" data-parking-capture hidden><legend>Yakalama</legend><div class="property-options">${['Var','Yok'].map(choice=>`<label><input type="radio" name="captureStatus" data-optional="true" value="${choice}" ${record.captureStatus===choice?'checked':''}> ${choice}</label>`).join('')}</div><div data-capture-details hidden><label class="field">Yakalama Açıklaması (isteğe bağlı)<textarea name="captureDetails" rows="3" data-optional="true" placeholder="Yakalama ile ilgili açıklamayı yazabilirsiniz…">${esc(record.captureDetails||'')}</textarea></label></div></fieldset>`}
function setupParkingCapture(form){const box=form.querySelector('[data-parking-capture]');if(!box)return;const parking=form.elements.docType?.value==='Yediemin Park Ücreti';box.hidden=!parking;const update=()=>{const show=parking&&form.querySelector('[name="captureStatus"]:checked')?.value==='Var';box.querySelector('[data-capture-details]').hidden=!show;const input=form.elements.captureDetails;input.disabled=!show;input.required=false;input.setCustomValidity('')};box.querySelectorAll('input').forEach(r=>{r.disabled=!parking;r.required=false;r.onchange=update});update()}

let insPeriod='day',insDate='',insEndDate='',insSort='collected';
function insPersonnelRows(events,staff,docs,period,date,endDate){
 const matches=value=>endDate?(String(value||'').slice(0,10)>=date&&String(value||'').slice(0,10)<=endDate):String(value||'').slice(0,period==='year'?4:period==='month'?7:10)===date.slice(0,period==='year'?4:period==='month'?7:10);
 const rows=staff.map(p=>({id:p.id,name:p.name,collected:0,closedCount:0,closedAmount:0,closedIds:new Set()}));
 const byId=new Map(rows.map(r=>[r.id,r]));
 for(const e of events){if(e.type!=='payment'||!matches(e.date))continue;const d=docs.find(d=>d.id===e.documentId);const id=e.turnoverStaffId||e.collectionStaffId||d?.relatedStaff||'unassigned';let row=byId.get(id);if(!row){row={id,name:e.turnoverStaffName||e.collectionStaffName||d?.relatedStaffName||'Personel atanmamış',collected:0,closedCount:0,closedAmount:0,closedIds:new Set()};byId.set(id,row);rows.push(row)}row.collected+=Number(e.amount||0);if(e.closes&&!row.closedIds.has(e.documentId||e.id)){row.closedIds.add(e.documentId||e.id);row.closedCount++;row.closedAmount+=Number(e.closedAmount||e.amount||0)}}
 return rows.map(({closedIds,...row})=>row).sort((a,b)=>b.collected-a.collected||a.name.localeCompare(b.name,'tr'))
}
function renderInsReportPage(){
 insDate=insDate||businessDate();insEndDate=insEndDate||insDate;const rows=insPersonnelRows(financeEvents,personnel,db.docs,insPeriod,insDate,insEndDate).sort((a,b)=>b[insSort]-a[insSort]||b.collected-a.collected||a.name.localeCompare(b.name,'tr')),total=rows.reduce((s,r)=>({collected:s.collected+r.collected,closedCount:s.closedCount+r.closedCount,closedAmount:s.closedAmount+r.closedAmount}),{collected:0,closedCount:0,closedAmount:0});
 const chart=(key,title,format)=>{const max=Math.max(1,...rows.map(r=>r[key]));return '<section class="ins-chart"><h3>'+title+'</h3>'+rows.map(r=>'<div class="ins-chart-row"><span>'+esc(r.name)+'</span><div class="ins-chart-track"><div class="ins-chart-bar" style="width:'+Math.max(0,r[key]/max*100)+'%"></div></div><strong>'+format(r[key])+'</strong></div>').join('')+'</section>'};
 $('#content').innerHTML='<div class="panel"><div class="panelhead"><div><h2>İNS Raporu</h2><p>Tüm personellerin tahsilat ve infaz performansı · Dosyanın tahsilat anındaki sorumlusuna göre</p></div><button class="secondary" id="backToReports">Raporlara Dön</button></div><div class="formbody"><div class="segments">'+[['day','Günlük'],['month','Aylık'],['year','Yıllık']].map(([key,label])=>'<button type="button" data-ins-period="'+key+'" class="'+(key===insPeriod?'selected':'')+'">'+label+'</button>').join('')+'</div>'+'<div class="grid">'+field('Başlangıç Tarihi','insDate','date',insDate,true)+field('Bitiş Tarihi','insEndDate','date',insEndDate,true)+'<label class="field">Sıralama<select id="insSort">'+[['collected','Tahsilat — Yüksekten Düşüğe'],['closedCount','İnfaz Adedi — Yüksekten Düşüğe'],['closedAmount','İnfaz Tutarı — Yüksekten Düşüğe']].map(([key,label])=>'<option value="'+key+'" '+(insSort===key?'selected':'')+'>'+label+'</option>').join('')+'</select></label></div><p>Seçilen tarih aralığı: <strong>'+displayDate(insDate)+' – '+displayDate(insEndDate)+'</strong></p><div class="overflow"><table><thead><tr><th>PERSONEL</th><th>TAHSİLAT</th><th>İNFAZ ADEDİ</th><th>İNFAZ TUTARI</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+esc(r.name)+'</td><td>'+money(r.collected/100)+'</td><td>'+r.closedCount+'</td><td>'+money(r.closedAmount/100)+'</td></tr>').join('')+'</tbody><tfoot><tr><th>TOPLAM</th><th>'+money(total.collected/100)+'</th><th>'+total.closedCount+'</th><th>'+money(total.closedAmount/100)+'</th></tr></tfoot></table></div><p>İnfaz tutarı, seçilen dönemde tamamen kapatılan dosyaların toplam tutarıdır.</p><div class="ins-charts">'+chart('collected','Tahsilat Grafiği',v=>money(v/100))+chart('closedCount','İnfaz Adedi Grafiği',v=>String(v))+chart('closedAmount','İnfaz Tutarı Grafiği',v=>money(v/100))+'</div></div></div>';
 $('#backToReports').onclick=reportsPage;$('#insSort').onchange=e=>{insSort=e.target.value;insReportPage()};document.querySelectorAll('[data-ins-period]').forEach(b=>b.onclick=()=>{insPeriod=b.dataset.insPeriod;const anchor=insDate;if(insPeriod==='day'){insEndDate=anchor}else if(insPeriod==='month'){insDate=anchor.slice(0,7)+'-01';const [y,m]=anchor.split('-').map(Number);insEndDate=anchor.slice(0,7)+'-'+new Date(Date.UTC(y,m,0)).getUTCDate()}else{insDate=anchor.slice(0,4)+'-01-01';insEndDate=anchor.slice(0,4)+'-12-31'}insReportPage()});function refreshInsRange(){const from=document.querySelector('[name="insDate"]'),to=document.querySelector('[name="insEndDate"]');to.setCustomValidity('');if(!from.value||!to.value)return;if(from.value>to.value){to.setCustomValidity('Bitiş tarihi başlangıç tarihinden önce olamaz.');to.reportValidity();return}insDate=from.value;insEndDate=to.value;insReportPage()}document.querySelector('[name="insDate"]').onchange=refreshInsRange;document.querySelector('[name="insEndDate"]').onchange=refreshInsRange;
}

function clientListReportRows(clients){return clients.map(c=>({name:c.fullName??(!c.type||c.type==='Şahıs'?c.name:''),category:c.clientCategory||'',tradeName:c.tradeName??(c.type&&c.type!=='Şahıs'?c.name:''),city:c.city||'',district:c.district||''})).sort((a,b)=>(a.name||a.tradeName||'').localeCompare(b.name||b.tradeName||'','tr'))}
function renderClientListReportPage(){const rows=clientListReportRows(db.clients),columns=[['name','Müvekkil Adı'],['category','Müvekkil Türü'],['tradeName','Müvekkil Unvanı'],['city','İl'],['district','İlçe']],table='<table><thead><tr>'+columns.map(([,title])=>'<th>'+title+'</th>').join('')+'</tr></thead><tbody>'+ (rows.map(r=>'<tr>'+columns.map(([key])=>'<td>'+esc(r[key]||'—')+'</td>').join('')+'</tr>').join('')||'<tr><td colspan="5" class="empty">Kayıtlı müvekkil bulunmuyor.</td></tr>')+'</tbody></table>';
 $('#content').innerHTML='<div class="panel"><div class="panelhead"><div><h2>Müvekkil Listesi</h2><p>'+rows.length+' müvekkil · '+displayDate(businessDate())+'</p></div><div class="toolbar"><button class="secondary" id="clientListBack">Raporlara Dön</button><button class="secondary" id="clientListPrint">Yazdır / PDF</button><button class="primary client-list-report-button" id="clientListCsv">CSV İndir</button></div></div><div class="overflow">'+table+'</div><div class="tablefoot">Toplam '+rows.length+' müvekkil</div></div>';
 $('#clientListBack').onclick=reportsPage;$('#clientListCsv').onclick=()=>{const lines=[columns.map(([,title])=>title),...rows.map(r=>columns.map(([key])=>r[key]))],blob=new Blob(['\uFEFF'+lines.map(line=>line.map(safeCsvCell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='muvekkil-listesi-'+businessDate()+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
 $('#clientListPrint').onclick=()=>{const frame=document.createElement('iframe');frame.style.cssText='position:fixed;width:0;height:0;border:0';document.body.append(frame);frame.onload=()=>{frame.contentWindow.focus();frame.contentWindow.print();setTimeout(()=>frame.remove(),60000)};frame.srcdoc='<!doctype html><html lang="tr"><meta charset="utf-8"><title>Müvekkil Listesi</title><style>body{font:12px Arial}table{border-collapse:collapse;width:100%}th,td{border:1px solid #ccc;padding:8px;text-align:left}th{background:#eee}@page{size:A4 landscape;margin:12mm}</style><h1>hanhukuk 1.1.1 · Müvekkil Listesi</h1><p>'+displayDate(businessDate())+' · '+rows.length+' müvekkil</p>'+table+'</html>'}
}

