 dialog.classList.add('compact-borrower-sheet');setupBorrowerResize(dialog);setupBorrowerDragging(dialog);setupBorrowerCornerResize(dialog);const head=dialog.querySelector(':scope > .panelhead'),body=dialog.querySelector(':scope > .formbody');head.querySelector('h2').textContent='Borçlu Föyü · '+d.number;const field=(label,value)=>'<div class="sheet-meta-field"><small>'+label+'</small><strong>'+esc(value||'—')+'</strong></div>';
