function setupFinanceOperationTabs(){const root=document.getElementById('modal'),nav=document.createElement('div');nav.className='settings-tabs finance-operation-tabs';nav.setAttribute('role','tablist');nav.setAttribute('aria-label','Tahsilat ve masraf işlemleri');const payment=root.querySelector('#financeEntry'),expense=root.querySelector('#expenseEntry'),terms=root.querySelector('#financeTerms');payment.before(nav);function select(key){financeOperationTab=key;payment.hidden=key!=='payment';expense.hidden=key!=='expense';terms.hidden=key!=='payment';nav.querySelectorAll('button').forEach(b=>{const active=b.dataset.operation===key;b.classList.toggle('selected',active);b.setAttribute('aria-selected',String(active))})}for(const [key,label] of [['payment','Tahsilat'],['expense','Masraf']]){const b=document.createElement('button');b.type='button';b.textContent=label;b.dataset.operation=key;b.setAttribute('role','tab');b.setAttribute('aria-controls',key==='payment'?'financeEntry':'expenseEntry');b.onclick=()=>select(key);nav.append(b)}terms.before(nav);select(financeOperationTab);root.addEventListener('invalid',e=>{if(expense.contains(e.target))select('expense');else if(payment.contains(e.target)||terms.contains(e.target))select('payment')},true)}

function borrowerClientInfo(id){const c=db.clients.find(c=>c.id===id);if(!c)return toast('Müvekkil kaydı bulunamadı.');let dialog=document.getElementById('borrowerClientInfo');if(!dialog){dialog=document.createElement('dialog');dialog.id='borrowerClientInfo';document.body.append(dialog)}const item=(label,value)=>'<div class="detail-field"><small>'+label+'</small><div>'+esc(value||'—')+'</div></div>',staff=id=>personnel.find(p=>p.id===id)?.name||'';dialog.innerHTML='<div class="panelhead"><div><h2>Müvekkil Bilgileri</h2><p>'+esc(c.name)+'</p></div><button type="button" class="secondary" id="closeClientInfo">Kapat</button></div><div class="formbody"><div class="grid">'+item('Ad Soyad',c.fullName??(c.type==='Şahıs'?c.name:''))+item('Ticari Unvan',c.tradeName??(c.type!=='Şahıs'?c.name:''))+item('Müvekkil Türü',c.clientCategory)+item('Şahıs / Şirket',c.type)+item('TC / Vergi Numarası',c.identity)+item('Telefon',c.phone)+item('E-posta',c.email)+item('İl / İlçe',[c.city,c.district].filter(Boolean).join(' / '))+item('Açık Adres',c.address)+(c.additionalPhones||[]).map((phone,i)=>item('Ek Telefon '+(i+1),phone)).join('')+(c.additionalAddresses||[]).map((a,i)=>item('Ek Adres '+(i+1),[a.address,a.district,a.city].filter(Boolean).join(' / '))).join('')+item('Referans',c.reference)+item('Evrak Alan',staff(c.documentStaff))+item('Evrak Kaydeden',staff(c.recordedBy)||c.recordedByName)+item('Tahsilat Uzmanı',staff(c.collectionStaff))+item('Banka',c.bankName)+item('Şube',c.bankBranch)+item('Hesap Sahibi',c.accountHolder)+item('IBAN',c.iban)+item('Notlar',c.notes)+'</div>'+clientAttachmentPreviews(c)+'</div>';dialog.querySelector('#closeClientInfo').onclick=()=>dialog.close();if(!dialog.open)dialog.showModal()}

function bindConversationResultFilter(root){const select=root.querySelector('[data-conversation-result-filter]');if(!select)return;const history=select.closest('.conversation-history'),rows=[...history.querySelectorAll('[data-conversation-result]')],count=history.querySelector('[data-conversation-filter-count]');function update(){let visible=0;for(const row of rows){row.hidden=!!select.value&&row.dataset.conversationResult!==select.value;if(!row.hidden)visible++}count.textContent=visible+' / '+rows.length+' görüşme'+(visible===0?' · Bu sonuç için görüşme bulunamadı.':'')}select.onchange=update;update()}

