function setupBorrowerNavigation(dialog,id){const ids=borrowerNavigationIds(id),index=ids.indexOf(id),nav=document.createElement('div');nav.className='borrower-sheet-navigation';nav.setAttribute('aria-label','Föyler arasında gezinme');for(const [direction,label,arrow,offset] of [['previous','Önceki','←',-1],['next','Sonraki','→',1]]){const button=document.createElement('button');button.type='button';button.className='secondary borrower-nav-arrow';button.dataset.sheetDirection=direction;button.setAttribute('aria-label',label+' föy');button.innerHTML='<span>'+label+'</span><strong aria-hidden="true">'+arrow+'</strong>';const target=ids[index+offset];button.disabled=index<0||!target;button.onclick=()=>{if(!target||blockIncompletePropertyClose(dialog))return;borrowerDetail(target)};nav.append(button)}const head=dialog.querySelector('.panelhead');if(head)head.append(nav)}

function setupBorrowerResize(dialog){const head=dialog.querySelector(':scope > .panelhead');if(!head)return;const button=document.createElement('button');button.type='button';button.className='secondary sheet-resize-toggle';button.setAttribute('aria-label','Föyü büyüt veya küçült');function update(){const expanded=dialog.classList.contains('sheet-maximized');button.textContent=expanded?'⊡ Küçült':'⛶ Büyüt';button.setAttribute('aria-pressed',String(expanded))}button.onclick=()=>{const expanded=dialog.classList.contains('sheet-maximized');if(!expanded){dialog._restoreSize={width:dialog.style.width,height:dialog.style.height};dialog.style.width='';dialog.style.height=''}else{dialog.style.width=Math.min(900,window.innerWidth*.9)+'px';dialog.style.height=Math.min(600,window.innerHeight*.75)+'px';if(dialog.style.left){const width=Math.min(900,window.innerWidth*.9),height=Math.min(600,window.innerHeight*.75);dialog.style.left=Math.max(0,Math.min(parseFloat(dialog.style.left)||0,window.innerWidth-width))+'px';dialog.style.top=Math.max(0,Math.min(parseFloat(dialog.style.top)||0,window.innerHeight-height))+'px'}}dialog.classList.toggle('sheet-maximized',!expanded);update()};head.append(button);update()}

function setupBorrowerDragging(dialog){const head=dialog.querySelector(':scope > .panelhead');if(!head)return;head.classList.add('sheet-drag-handle');head.title='Föyü taşımak için başlık alanından sürükleyin';head.onpointerdown=e=>{if(e.button!==0||e.target.closest('button,input,select,textarea,a'))return;const rect=dialog.getBoundingClientRect(),offsetX=e.clientX-rect.left,offsetY=e.clientY-rect.top;dialog.style.position='fixed';dialog.style.margin='0';dialog.style.right='auto';dialog.style.bottom='auto';dialog.style.left=rect.left+'px';dialog.style.top=rect.top+'px';head.setPointerCapture(e.pointerId);e.preventDefault();const move=event=>{dialog.style.left=Math.max(0,Math.min(window.innerWidth-dialog.getBoundingClientRect().width,event.clientX-offsetX))+'px';dialog.style.top=Math.max(0,Math.min(window.innerHeight-50,event.clientY-offsetY))+'px'};const stop=()=>{head.removeEventListener('pointermove',move);head.removeEventListener('pointerup',stop);head.removeEventListener('pointercancel',stop);try{head.releasePointerCapture(e.pointerId)}catch{}};head.addEventListener('pointermove',move);head.addEventListener('pointerup',stop);head.addEventListener('pointercancel',stop)}}

function setupBorrowerCornerResize(dialog){for(const corner of ['nw','ne','sw','se']){const handle=document.createElement('div');handle.className='sheet-corner-resize sheet-corner-'+corner;handle.setAttribute('aria-hidden','true');dialog.append(handle);handle.onpointerdown=e=>{if(e.button!==0||dialog.classList.contains('sheet-maximized'))return;e.preventDefault();e.stopPropagation();const r=dialog.getBoundingClientRect(),startX=e.clientX,startY=e.clientY;dialog.style.position='fixed';dialog.style.margin='0';dialog.style.right='auto';dialog.style.bottom='auto';dialog.style.left=r.left+'px';dialog.style.top=r.top+'px';dialog.style.width=r.width+'px';dialog.style.height=r.height+'px';handle.setPointerCapture(e.pointerId);const move=event=>{const west=corner.includes('w'),north=corner.includes('n'),minWidth=Math.min(680,window.innerWidth*.94),minHeight=Math.min(360,window.innerHeight*.9);let left=r.left,right=r.right,top=r.top,bottom=r.bottom;if(west)left=Math.max(0,Math.min(right-minWidth,r.left+event.clientX-startX));else right=Math.min(window.innerWidth,Math.max(left+minWidth,r.right+event.clientX-startX));if(north)top=Math.max(0,Math.min(bottom-minHeight,r.top+event.clientY-startY));else bottom=Math.min(window.innerHeight,Math.max(top+minHeight,r.bottom+event.clientY-startY));dialog.style.left=left+'px';dialog.style.top=top+'px';dialog.style.width=right-left+'px';dialog.style.height=bottom-top+'px'};const stop=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',stop);handle.removeEventListener('pointercancel',stop);try{handle.releasePointerCapture(e.pointerId)}catch{}};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',stop);handle.addEventListener('pointercancel',stop)}}}

function setupBorrowerPin(dialog,d){const head=dialog.querySelector(':scope > .panelhead'),pin=document.createElement('button');pin.type='button';pin.className='secondary sheet-pin-button';pin.textContent='📌';pin.title='Föyü ekranda iğnele';pin.setAttribute('aria-label','Föyü iğnele');head.prepend(pin);pin.onclick=()=>{const existing=[...document.querySelectorAll('.pinned-borrower-sheet')].find(p=>p.dataset.pinnedDocument===d.id);if(existing){dialog.close();existing.focus();return}const pinned=document.createElement('dialog');pinned.className='compact-borrower-sheet pinned-borrower-sheet';pinned.dataset.pinnedDocument=d.id;pinned.innerHTML=dialog.innerHTML;pinned.querySelectorAll('[id]').forEach(el=>el.removeAttribute('id'));pinned.querySelectorAll('.sheet-corner-resize').forEach(el=>el.remove());pinned.querySelectorAll('input,select,textarea,button').forEach(el=>el.disabled=true);const pinnedHead=pinned.querySelector(':scope > .panelhead');pinnedHead.innerHTML='<strong>📌 '+esc(d.number)+' · '+esc(d.debtor)+'</strong><div class="toolbar"><button type="button" class="secondary" data-pin-open>Föyü Aç</button><button type="button" class="secondary close-align-right" data-pin-close>Kapat</button></div>';pinnedHead.querySelector('[data-pin-close]').onclick=()=>pinned.remove();pinnedHead.querySelector('[data-pin-open]').onclick=()=>{const rect=pinned.getBoundingClientRect();pinned.remove();borrowerDetail(d.id);const active=document.getElementById('borrowerDetail');active.classList.remove('sheet-maximized');Object.assign(active.style,{position:'fixed',margin:'0',left:rect.left+'px',top:rect.top+'px',right:'auto',bottom:'auto',width:rect.width+'px',height:rect.height+'px'})};pinned.querySelectorAll('[data-borrower-tab]').forEach(b=>{b.disabled=false;b.onclick=()=>{const key=b.dataset.borrowerTab;pinned.querySelectorAll('[data-borrower-panel]').forEach(panel=>panel.hidden=panel.dataset.borrowerPanel!==key);pinned.querySelectorAll('[data-borrower-tab]').forEach(tab=>tab.classList.toggle('selected',tab===b))}});const count=document.querySelectorAll('.pinned-borrower-sheet').length;pinned.style.left=Math.min(30+count*35,window.innerWidth*.3)+'px';pinned.style.top=Math.min(35+count*35,window.innerHeight*.25)+'px';document.body.append(pinned);setupBorrowerDragging(pinned);dialog.close();pinned.show()}}

function setupBorrowerChain(dialog,d){const button=document.createElement('button');button.type='button';button.className='secondary sheet-chain-button';const count=(d.linkedDocumentIds||[]).filter(id=>db.docs.some(x=>x.id===id)).length;button.textContent='🔗 Zincir Yap'+(count?' ('+count+')':'');button.onclick=()=>openBorrowerChain(d.id);dialog.querySelector(':scope > .panelhead').append(button)}
function openBorrowerChain(id){const d=db.docs.find(d=>d.id===id);if(!d)return;let dialog=document.getElementById('borrowerChainDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='borrowerChainDialog';document.body.append(dialog)}dialog.innerHTML='<div class="panelhead"><div><h2>Dosya Zinciri</h2><p>'+esc(d.number)+' · '+esc(d.debtor)+'</p></div><button type="button" class="secondary" data-chain-close>Kapat</button></div><div class="formbody"><p>Dosyaları birbirine bağlayın. Bağlantı, dosyaların borç ve ödeme hesaplarını değiştirmez.</p><h3>Bağlı Dosyalar</h3><div data-chain-linked></div><label class="field">Bağlanacak Dosyayı Ara<input type="search" data-chain-search data-optional="true" placeholder="Föy no, borçlu, TC veya müvekkil…"></label><div data-chain-results></div></div>';dialog.querySelector('[data-chain-close]').onclick=()=>dialog.close();function update(action,targetId){try{const result=authApi('/api/documents/chain','POST',{documentId:id,targetId,action});for(const record of result.documents){const existing=db.docs.find(x=>x.id===record.id);if(existing)Object.assign(existing,record)}render();const parent=document.getElementById('borrowerDetail');if(parent?.open)borrowerDetail(id);toast(action==='add'?'Dosyalar zincir yapılarak kaydedildi.':'Dosya bağlantısı kaldırıldı.',dialog)}catch(error){toast(error.message,dialog)}}function render(){const linked=new Set(d.linkedDocumentIds||[]),row=(x,isLinked)=>'<div class="chain-file-row"><div><strong>'+esc(x.number)+' · '+esc(x.debtor)+'</strong><small>'+esc(db.clients.find(c=>c.id===x.client)?.name||'')+' · '+esc(debtorStatus(x))+'</small></div>'+(isLinked?'<button class="secondary" data-chain-open="'+esc(x.id)+'">Föyü Aç</button><button class="link" data-chain-remove="'+esc(x.id)+'">Bağı Kaldır</button>':'<button class="primary" data-chain-add="'+esc(x.id)+'">Zincire Ekle</button>')+'</div>';dialog.querySelector('[data-chain-linked]').innerHTML=db.docs.filter(x=>linked.has(x.id)).map(x=>row(x,true)).join('')||'<p>Bağlı dosya bulunmuyor.</p>';const query=dialog.querySelector('[data-chain-search]').value.trim().toLocaleLowerCase('tr');const candidates=db.docs.filter(x=>x.id!==id&&!linked.has(x.id)&&[x.number,x.debtor,x.identity,db.clients.find(c=>c.id===x.client)?.name].some(value=>normalizeSearch(value).includes(normalizeSearch(query))));dialog.querySelector('[data-chain-results]').innerHTML=candidates.slice(0,50).map(x=>row(x,false)).join('')||'<p>Eşleşen dosya yok.</p>';dialog.querySelectorAll('[data-chain-add]').forEach(b=>b.onclick=()=>update('add',b.dataset.chainAdd));dialog.querySelectorAll('[data-chain-remove]').forEach(b=>b.onclick=()=>update('remove',b.dataset.chainRemove));dialog.querySelectorAll('[data-chain-open]').forEach(b=>b.onclick=()=>{dialog.close();borrowerDetail(b.dataset.chainOpen)})}dialog.querySelector('[data-chain-search]').oninput=render;render();if(!dialog.open)dialog.showModal()}

function borrowerAttachmentPreviews(d){const pdf=typeof d.fileData==='string'&&/^data:application\/pdf;base64,/i.test(d.fileData)?d.fileData:'',photo=typeof d.photoData==='string'&&/^data:image\/(png|jpeg|jpg);base64,/i.test(d.photoData)?d.photoData:'';if(!pdf&&!photo)return '<p class="notice">Bu evrak için yüklenmiş fotoğraf veya PDF bulunmuyor.</p>';return '<div class="borrower-attachment-previews">'+(photo?'<section><h3>Kaydedilen Fotoğraf</h3><img class="borrower-document-photo" src="'+esc(photo)+'" alt="'+esc(d.photoFileName||'Evrak fotoğrafı')+'"><p><a href="'+esc(photo)+'" download="'+esc(d.photoFileName||'evrak-fotografi')+'">Fotoğrafı İndir</a></p></section>':'')+(pdf?'<section><h3>Kaydedilen PDF</h3><object class="borrower-document-pdf" data="'+esc(pdf)+'" type="application/pdf"><p>PDF önizlemesi bu tarayıcıda gösterilemiyor. Aşağıdaki bağlantıdan indirebilirsiniz.</p></object><p><a href="'+esc(pdf)+'" download="'+esc(d.fileName||'evrak.pdf')+'">PDF İndir · '+esc(d.fileName||'Evrak')+'</a></p></section>':'')+'</div>'}

function moveRepaymentToAccount(dialog,summary){const panel=dialog.querySelector('[data-borrower-panel="finance"]');if(!panel)return;panel.removeAttribute('data-borrower-panel');panel.removeAttribute('role');panel.removeAttribute('aria-labelledby');panel.hidden=false;panel.classList.add('sheet-account-extra');panel.querySelector('.stats')?.remove();panel.querySelectorAll('h3.sectiontitle').forEach(el=>el.remove());const financial=panel.querySelector('#borrowerFinancial'),expense=panel.querySelector('#borrowerExpense');financial.hidden=true;expense.hidden=true;const actions=document.createElement('div');actions.className='sheet-debt-actions';const repayment=panel.querySelector('#openRepayment'),promise=panel.querySelector('[data-payment-promise]');if(repayment)actions.append(repayment);if(promise)actions.append(promise);summary.append(actions);const status=panel.querySelector('#borrowerStatusForm'),statusDetails=document.createElement('details');statusDetails.innerHTML='<summary>Dosya Durumu</summary>';if(status){statusDetails.append(status);summary.append(statusDetails)}const details=document.createElement('details');details.className='sheet-repayment-details';details.innerHTML='<summary>Yapılandırma / Ödeme Sözü Bilgileri</summary>';details.append(panel);summary.append(details)}

function moveSheetActionsToHeader(dialog,summary,documentRecord){const head=dialog.querySelector(':scope > .panelhead'),toolbar=document.createElement('div');toolbar.className='sheet-header-actions';for(const selector of ['#sheetOpenFinance','[data-payment-promise]','#sheetOpenExpense','#openRepayment']){const button=summary.querySelector(selector);if(button)toolbar.append(button)}if(documentRecord&&debtorStatus(documentRecord)==='İnfaz'){const release=document.createElement('button');release.type='button';release.className='secondary sheet-release-button';release.textContent='İbraname';release.onclick=()=>openBorrowerRelease(documentRecord.id);const payment=toolbar.querySelector('#sheetOpenFinance');if(payment)payment.after(release);else toolbar.append(release)}const status=summary.querySelector('details:not(.sheet-repayment-details)');if(status){status.hidden=true;const statusField=document.createElement('label');statusField.className='sheet-inline-status';statusField.append(document.createTextNode('Dosya Durumu'));const statusSelect=document.createElement('select');statusSelect.setAttribute('aria-label','Dosya Durumu');statusSelect.dataset.optional='true';const current=dialog.querySelector('#borrowerStatusForm select').value;for(const [value,label] of [['Derdest','Derdest'],['İcra','İcrada'],['İade','İade'],['İnfaz','İnfaz']]){const option=new Option(label,value);if(value==='İade'&&!['ceo','admin'].includes(hanAuth.role))option.disabled=true;statusSelect.add(option)}statusSelect.value=current;function paint(){statusSelect.dataset.statusColor=({'Derdest':'green','İcra':'orange','İade':'yellow','İnfaz':'red'})[statusSelect.value]}paint();statusSelect.onchange=()=>{const form=dialog.querySelector('#borrowerStatusForm');form.elements.status.value=statusSelect.value;form.requestSubmit();const record=db.docs.find(d=>d.id===dialog.dataset.borrowerId);statusSelect.value=record?debtorStatus(record):current;paint()};statusField.append(statusSelect);toolbar.append(statusField)}const info=document.createElement('button');info.type='button';info.className='secondary';info.textContent='Yapılandırma / Ödeme Sözü Bilgileri';info.onclick=()=>openSheetPlanInfo(dialog);toolbar.append(info);const planDetails=summary.querySelector('.sheet-repayment-details');if(planDetails)planDetails.hidden=true;head.append(toolbar);const resize=head.querySelector('.sheet-resize-toggle'),close=head.querySelector('#closeBorrower');if(resize&&close)close.before(resize)}

function openSheetPlanInfo(source){const original=source.querySelector('.sheet-repayment-details .sheet-account-extra');if(!original)return;let dialog=document.getElementById('sheetPlanInfoDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='sheetPlanInfoDialog';document.body.append(dialog)}dialog.innerHTML='<div class="panelhead"><h2>Yapılandırma / Ödeme Sözü Bilgileri</h2><button type="button" class="secondary close-align-right" data-close-plan-info>Kapat</button></div><div class="formbody" data-plan-info-content></div>';const content=original.cloneNode(true);content.removeAttribute('id');content.querySelectorAll('[id]').forEach(el=>el.removeAttribute('id'));content.querySelectorAll('button,form').forEach(el=>el.remove());content.hidden=false;dialog.querySelector('[data-plan-info-content]').append(content);dialog.querySelector('[data-close-plan-info]').onclick=()=>dialog.close();if(!dialog.open)dialog.showModal()}

function openSheetStatus(source){const form=source.querySelector('#borrowerStatusForm');if(!form)return;let dialog=document.getElementById('sheetStatusDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='sheetStatusDialog';document.body.append(dialog)}dialog.innerHTML='<div class="panelhead"><h2>Dosya Durumu</h2><button type="button" class="secondary close-align-right" data-status-close>Kapat</button></div><div class="formbody" data-status-host></div>';const parent=form.parentNode;dialog.querySelector('[data-status-host]').append(form);function restore(){if(form.parentNode)parent.append(form)}dialog.addEventListener('close',restore,{once:true});dialog.querySelector('[data-status-close]').onclick=()=>dialog.close();const originalSubmit=form.onsubmit;form.onsubmit=e=>{originalSubmit.call(form,e);const current=db.docs.find(d=>d.id===source.dataset.borrowerId);if(current&&debtorStatus(current)===form.elements.status.value){dialog.close()}else{const note=document.createElement('p');note.className='notice';note.textContent='Durum değiştirilemedi. Dosyanın ödeme ve durum koşullarını kontrol edin.';dialog.querySelector('[data-status-host]').append(note)}};dialog.addEventListener('close',()=>{form.onsubmit=originalSubmit},{once:true});if(!dialog.open)dialog.showModal()}

function borrowerReleaseContent(d,client){const payments=financeEvents.filter(e=>e.documentId===d.id&&e.type==='payment'),paidDate=d.closedDate||payments.map(e=>e.date).sort().at(-1)||'',tracking=borrowerTrackingDate(d);return '<article class="release-letter"><h1>İBRANAME</h1><p class="release-addressee">Sn. '+esc(d.debtor)+'</p><p>Alacaklı '+esc(client?.tradeName||client?.name||'—')+' firmaya '+esc(displayDate(paidDate)||'—')+' tarihinde ödeme yaptığınız için, '+esc(displayDate(tracking)||'—')+' takip tarihli '+esc(d.number)+' numaralı dosyanızdan borcunuz kalmamıştır.</p><div class="release-signature"><strong>Av. Hasan Bahadır PATAN</strong></div></article>'}
function openBorrowerRelease(id){const d=db.docs.find(d=>d.id===id);if(!d||debtorStatus(d)!=='İnfaz'||docFinance(d).remaining>0)return toast('İbraname yalnızca borcu tamamen ödenmiş infaz dosyalarında oluşturulur.');const client=db.clients.find(c=>c.id===d.client),letter=borrowerReleaseContent(d,client);let dialog=document.getElementById('borrowerReleaseDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='borrowerReleaseDialog';document.body.append(dialog)}dialog.innerHTML='<div class="panelhead"><h2>İbraname · '+esc(d.number)+'</h2><div class="toolbar"><button type="button" class="primary" data-print-release>Yazdır / PDF</button><button type="button" class="secondary close-align-right" data-close-release>Kapat</button></div></div><div class="formbody">'+letter+'</div>';dialog.querySelector('[data-close-release]').onclick=()=>dialog.close();dialog.querySelector('[data-print-release]').onclick=()=>{const frame=document.createElement('iframe');frame.style.cssText='position:fixed;width:0;height:0;border:0';document.body.append(frame);frame.onload=()=>{frame.contentWindow.focus();frame.contentWindow.print();setTimeout(()=>frame.remove(),60000)};frame.srcdoc='<!doctype html><html lang="tr"><meta charset="utf-8"><title>İbraname '+esc(d.number)+'</title><style>@page{size:A4;margin:25mm}body{font:12pt Arial;color:#111}.release-letter h1{text-align:center;font-size:18pt;margin:25mm 0 20mm}.release-letter p{line-height:1.9;text-align:justify}.release-addressee{font-weight:bold}.release-signature{text-align:right;margin-top:30mm}</style>'+letter+'</html>'};if(!dialog.open)dialog.showModal()}

function collectionReceiptContent(event,d,client){const item=(label,value)=>'<tr><th>'+label+'</th><td>'+esc(value||'—')+'</td></tr>';return '<article class="collection-receipt-document"><h1>TAHSİLAT MAKBUZU</h1><p class="receipt-reference">Makbuz No: '+esc(event.id)+'</p><table>'+item('Tahsilat Tarihi',displayDate(event.date))+item('Föy Numarası',d.number)+item('Takip Tarihi',displayDate(borrowerTrackingDate(d)))+item('Borçlu',d.debtor)+item('TC / Vergi No',d.identity)+item('Alacaklı',client?.tradeName||client?.name)+item('Tahsil Edilen Tutar',money(event.amount/100))+item('Kasa / Banka',event.accountName||accounting.accounts.find(a=>a.id===event.accountId)?.name)+item('Tahsil Eden','Av. Hasan Bahadır Patan Hukuk Bürosu')+item('Açıklama / Dekont No',event.note)+'</table><p>Yukarıda belirtilen dosyaya ilişkin '+esc(money(event.amount/100))+' tutarındaki ödeme tahsil edilmiştir.</p><div class="receipt-signatures"><div>Ödemeyi Yapan<br><strong>'+esc(d.debtor)+'</strong><br>İmza</div><div>Tahsil Eden<br><strong>Av. Hasan Bahadır Patan Hukuk Bürosu</strong><br>İmza</div></div></article>'}
function openCollectionReceipt(eventId){const event=financeEvents.find(e=>e.id===eventId&&e.type==='payment');if(!event)return toast('Kayıtlı tahsilat bulunamadı.');const d=db.docs.find(d=>d.id===event.documentId);if(!d)return;const letter=collectionReceiptContent(event,d,db.clients.find(c=>c.id===d.client));let dialog=document.getElementById('collectionReceiptDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='collectionReceiptDialog';document.body.append(dialog)}dialog.innerHTML='<div class="panelhead"><h2>Tahsilat Makbuzu</h2><div class="toolbar"><button type="button" class="primary" data-receipt-print>Yazdır / PDF</button><button type="button" class="secondary close-align-right" data-receipt-close>Kapat</button></div></div><div class="formbody">'+letter+'</div>';dialog.querySelector('[data-receipt-close]').onclick=()=>dialog.close();dialog.querySelector('[data-receipt-print]').onclick=()=>{const frame=document.createElement('iframe');frame.style.cssText='position:fixed;width:0;height:0;border:0';document.body.append(frame);frame.onload=()=>{frame.contentWindow.focus();frame.contentWindow.print();setTimeout(()=>frame.remove(),60000)};frame.srcdoc='<!doctype html><html lang="tr"><meta charset="utf-8"><title>Tahsilat Makbuzu '+esc(d.number)+'</title><style>@page{size:A4;margin:22mm}body{font:11pt Arial;color:#111}h1{text-align:center;font-size:19pt;margin:25px 0}table{width:100%;border-collapse:collapse}th,td{border:1px solid #bbb;text-align:left;padding:10px}th{width:34%}.receipt-reference{font-size:9pt;overflow-wrap:anywhere}.receipt-signatures{display:flex;justify-content:space-between;margin-top:65px;line-height:2}</style>'+letter+'</html>'};if(!dialog.open)dialog.showModal()}

let reportDataSnapshot=null;
function withReportData(callback){if(!reportDataSnapshot||['ceo','admin'].includes(hanAuth.role))return callback();const previous={db,personnel,financeEvents,accounting};try{db=reportDataSnapshot.db;personnel=reportDataSnapshot.personnel;financeEvents=reportDataSnapshot.financeEvents;accounting=reportDataSnapshot.accounting;return callback()}finally{db=previous.db;personnel=previous.personnel;financeEvents=previous.financeEvents;accounting=previous.accounting}}
function reportsPage(){if(!['ceo','admin'].includes(hanAuth.role)){try{reportDataSnapshot=authApi('/api/report-data')}catch(error){return toast(error.message)}}return withReportData(renderReportsPage)}
function currentReport(){return withReportData(buildCurrentReport)}
function insReportPage(){return withReportData(renderInsReportPage)}
function clientListReportPage(){return withReportData(renderClientListReportPage)}

function setupBorrowerDeletion(dialog,d){if(!['ceo','admin'].includes(hanAuth.role))return;const button=document.createElement('button');button.type='button';button.className='secondary sheet-delete-button';button.textContent='Dosyayı Sil';button.onclick=()=>deleteBorrowerDocument(d.id);dialog.querySelector(':scope > .panelhead .toolbar').prepend(button)}
function deleteBorrowerDocument(id){if(!['ceo','admin'].includes(hanAuth.role))return;const d=db.docs.find(d=>d.id===id);if(!d||!confirm(d.number+' · '+d.debtor+' dosyasını silmek istiyor musunuz? Tahsilat ve kasa hareketleri korunacaktır.'))return;try{authApi('/api/documents/delete','POST',{documentId:id});db.docs=db.docs.filter(d=>d.id!==id);for(const doc of db.docs)doc.linkedDocumentIds=(doc.linkedDocumentIds||[]).filter(target=>target!==id);const detail=document.getElementById('borrowerDetail');if(detail?.open)detail.close();document.querySelectorAll('.pinned-borrower-sheet').forEach(p=>{if(p.dataset.pinnedDocument===id)p.remove()});page='documents';render();toast('Dosya silindi.')}catch(error){toast(error.message)}}

function clientAttachmentPreviews(c){const files=(Array.isArray(c.attachments)?c.attachments:[]).filter(f=>typeof f.data==='string'&&/^data:(application\/pdf|image\/(jpeg|jpg|png|webp));base64,/i.test(f.data));return '<section class="client-poa-previews"><h3>Vekâletname / Yüklenen Belgeler</h3>'+(files.map(f=>{const pdf=/^data:application\/pdf;/i.test(f.data);return '<article class="client-poa-file"><h4>'+esc(f.name|| (pdf?'Vekâletname PDF':'Vekâletname / Fotoğraf'))+'</h4>'+(pdf?'<object type="application/pdf" data="'+esc(f.data)+'" class="borrower-document-pdf"><p>PDF önizlemesi desteklenmiyor. Aşağıdaki bağlantıdan indirebilirsiniz.</p></object>':'<img class="borrower-document-photo" src="'+esc(f.data)+'" alt="'+esc(f.name||'Müvekkil belgesi')+'">')+'<p><a href="'+esc(f.data)+'" download="'+esc(f.name||'vekaletname')+'">İndir</a></p></article>'}).join('')||'<p>Bu müvekkile yüklenmiş vekâletname veya fotoğraf bulunmuyor.</p>')+'</section>'}

let monthlyPayrollReportMonth='';
function monthlyPayrollReportPage(){monthlyPayrollReportMonth=monthlyPayrollReportMonth||businessDate().slice(0,7);let data;try{data=authApi('/api/payroll-report?month='+monthlyPayrollReportMonth)}catch(error){return toast(error.message)}const columns=[['name','Personel'],['department','Birim'],['salary','Maaş'],['bonus1','Prim 1'],['bonus2','Prim 2'],['dailyBonus','Günlük Prim'],['total','Genel Toplam']],totals=data.rows.reduce((s,r)=>{for(const key of ['salary','bonus1','bonus2','dailyBonus','total'])s[key]+=r[key];return s},{salary:0,bonus1:0,bonus2:0,dailyBonus:0,total:0}),table='<table><thead><tr>'+columns.map(([,label])=>'<th>'+label+'</th>').join('')+'</tr></thead><tbody>'+data.rows.map(r=>'<tr>'+columns.map(([key],i)=>'<td>'+esc(i<2?r[key]||'—':money(r[key]/100))+'</td>').join('')+'</tr>').join('')+'</tbody><tfoot><tr><th colspan="2">ALT TOPLAM</th>'+['salary','bonus1','bonus2','dailyBonus','total'].map(key=>'<th>'+money(totals[key]/100)+'</th>').join('')+'</tr></tfoot></table>';$('#content').innerHTML='<div class="panel"><div class="panelhead"><div><h2>Aylık Maaş ve Prim Raporu</h2><p>'+data.month+' · '+(data.closed?'Geçmiş dönem':'Güncel dönem')+'</p></div><div class="toolbar"><label class="field">Rapor Ayı<input type="month" data-payroll-report-month data-optional="true" value="'+data.month+'"></label><button class="secondary" data-payroll-report-back>Raporlara Dön</button><button class="secondary" data-payroll-report-print>Yazdır / PDF</button><button class="primary" data-payroll-report-csv>CSV İndir</button></div></div>'+(data.missing?'<div class="formbody notice">Bu ay için kayıtlı maaş ve prim dönemi bulunmuyor.</div>':'')+'<div class="overflow">'+table+'</div><div class="formbody"><p>Prim 2 ve günlük primler yalnızca seçilen aya aittir. Geçmiş dönem maaş ve primleri dönem kaydından gösterilir.</p></div></div>';document.querySelector('[data-payroll-report-month]').onchange=e=>{if(e.target.value){monthlyPayrollReportMonth=e.target.value;monthlyPayrollReportPage()}};document.querySelector('[data-payroll-report-back]').onclick=reportsPage;document.querySelector('[data-payroll-report-csv]').onclick=()=>{const lines=[columns.map(([,label])=>label),...data.rows.map(r=>columns.map(([key],i)=>i<2?r[key]||'':money(r[key]/100))),['ALT TOPLAM','',...['salary','bonus1','bonus2','dailyBonus','total'].map(key=>money(totals[key]/100))]],blob=new Blob(['\uFEFF'+lines.map(row=>row.map(safeCsvCell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='maas-prim-'+data.month+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};document.querySelector('[data-payroll-report-print]').onclick=()=>{const frame=document.createElement('iframe');frame.style.cssText='position:fixed;width:0;height:0;border:0';document.body.append(frame);frame.onload=()=>{frame.contentWindow.focus();frame.contentWindow.print();setTimeout(()=>frame.remove(),60000)};frame.srcdoc='<!doctype html><html lang="tr"><meta charset="utf-8"><title>Maaş ve Prim '+data.month+'</title><style>@page{size:A4 landscape;margin:15mm}body{font:11px Arial}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ccc;padding:8px;text-align:left}</style><h1>Maaş ve Prim Raporu · '+data.month+'</h1>'+table+'</html>'}}
